            "guid" => crate::rand::guid(),
            "category" => "room",
            "level" => ctx.level_guid(level),
            "point" => Value::Arr(vec![Value::f(point[0]), Value::f(point[1])]),
            "name" => name.unwrap_or_else(|| "Room".to_string()),
            "number" => number.unwrap_or_default(),
        };
        ctx.add(r.id, "room", v);
    }
}

