    open(os.path.join(d, 's.txt'), 'w').write('\n'.join(lines) + '\n')
    p = subprocess.run([exe, 'run', '--script', 's.txt', '--save', 'o.bimcraft'], cwd=d, capture_output=True)
    out = []
    if p.returncode:
        out.append('ERR ' + p.stderr.decode().strip())
    else:
        out.append(p.stdout.decode().strip().split('\n')[-2])
        doc = json.load(open(os.path.join(d, 'o.bimcraft')))
        for k, v in doc['elements'].items():
            if v['category'] in cats:
                out.append(k + ' ' + ' '.join('%s=%s' % (kk, json.dumps(v.get(kk))) for kk in keys if kk in v))
