//! Plan geometry: points and vectors, polygons (area, orientation, containment), segments and
//! their crossings, arcs as chords, the planar graph of lines and its faces, offsets, sketches,
//! triangulation and straight skeletons. Everything in millimetres, in the plan's x and y.

pub mod graph;
pub mod sketch;
pub mod offset;
pub mod tri;

pub type P2 = [f64; 2];

#[inline]
pub fn add(a: P2, b: P2) -> P2 {
    [a[0] + b[0], a[1] + b[1]]
}
#[inline]
pub fn sub(a: P2, b: P2) -> P2 {
    [a[0] - b[0], a[1] - b[1]]
}
#[inline]
pub fn scale(a: P2, k: f64) -> P2 {
    [a[0] * k, a[1] * k]
}
#[inline]
pub fn dot(a: P2, b: P2) -> f64 {
    a[0] * b[0] + a[1] * b[1]
}
#[inline]
pub fn cross(a: P2, b: P2) -> f64 {
    a[0] * b[1] - a[1] * b[0]
}
#[inline]
pub fn len(a: P2) -> f64 {
    (a[0] * a[0] + a[1] * a[1]).sqrt()
}
#[inline]
pub fn dist(a: P2, b: P2) -> f64 {
    let dx = b[0] - a[0];
    let dy = b[1] - a[1];
    (dx * dx + dy * dy).sqrt()
}
#[inline]
pub fn lerp(a: P2, b: P2, t: f64) -> P2 {
    [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]
}
/// The unit vector along a, or zero.
pub fn unit(a: P2) -> P2 {
    let l = len(a);
    if l > 0.0 {
        [a[0] / l, a[1] / l]
    } else {
        [0.0, 0.0]
    }
}
/// The vector turned a quarter turn counter-clockwise (to the left).
#[inline]
pub fn left(a: P2) -> P2 {
    [-a[1], a[0]]
}
/// (b - a) x (c - a): positive when c is left of a→b.
#[inline]
pub fn orient(a: P2, b: P2, c: P2) -> f64 {
    (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
}

/// The signed area of a ring (counter-clockwise positive), by the shoelace sum.
pub fn area(ring: &[P2]) -> f64 {
    let n = ring.len();
    if n < 3 {
        return 0.0;
    }
    let mut s = 0.0;
    for i in 0..n {
        let a = ring[i];
        let b = ring[(i + 1) % n];
        s += a[0] * b[1] - b[0] * a[1];
    }
    s / 2.0
}

pub fn perimeter(ring: &[P2]) -> f64 {
    let n = ring.len();
    let mut s = 0.0;
    for i in 0..n {
        s += dist(ring[i], ring[(i + 1) % n]);
    }
    s
}

/// The ring counter-clockwise: reversed (whole) if it runs clockwise.
pub fn ccw(ring: &[P2]) -> Vec<P2> {
    if area(ring) < 0.0 {
        ring.iter().rev().copied().collect()
    } else {
        ring.to_vec()
    }
}

/// The ring clockwise: reversed (whole) if it runs counter-clockwise.
pub fn cw(ring: &[P2]) -> Vec<P2> {
    if area(ring) > 0.0 {
        ring.iter().rev().copied().collect()
    } else {
        ring.to_vec()
    }
}

/// The parameter along a→b of the point nearest p, clamped to the segment.
pub fn project_t(a: P2, b: P2, p: P2) -> f64 {
    let d = sub(b, a);
    let l2 = dot(d, d);
    if l2 <= 0.0 {
        return 0.0;
    }
    (dot(sub(p, a), d) / l2).clamp(0.0, 1.0)
}

/// How far p is from the segment a–b.
pub fn seg_dist(a: P2, b: P2, p: P2) -> f64 {
    let t = project_t(a, b, p);
    dist(p, lerp(a, b, t))
}

/// Whether p lies inside the ring (even-odd; a point on an edge counts as outside).
pub fn inside(ring: &[P2], p: P2) -> bool {
    let n = ring.len();
    if n < 3 {
        return false;
    }
    for i in 0..n {
        let a = ring[i];
        let b = ring[(i + 1) % n];
        if seg_dist(a, b, p) < 1e-9 {
            return false;
        }
    }
    inside_raw(ring, p)
}

/// Even-odd containment without the edge test.
pub fn inside_raw(ring: &[P2], p: P2) -> bool {
    let n = ring.len();
    let mut c = false;
    let mut j = n - 1;
    for i in 0..n {
        let a = ring[i];
        let b = ring[j];
        if (a[1] > p[1]) != (b[1] > p[1]) {
            let x = (b[0] - a[0]) * (p[1] - a[1]) / (b[1] - a[1]) + a[0];
            if p[0] < x {
                c = !c;
            }
        }
        j = i;
    }
    c
}

/// Where two segments cross, as parameters (t along a0→a1, u along b0→b1), when they cross at a
/// single point (ends included).
pub fn seg_cross(a0: P2, a1: P2, b0: P2, b1: P2) -> Option<(f64, f64)> {
    let d = sub(a1, a0);
    let e = sub(b1, b0);
    let den = cross(d, e);
    if den == 0.0 {
        return None;
    }
    let w = sub(b0, a0);
    let t = cross(w, e) / den;
    let u = cross(w, d) / den;
    if (0.0..=1.0).contains(&t) && (0.0..=1.0).contains(&u) {
        Some((t, u))
    } else {
        None
    }
}

/// The bounding box of points: (min, max).
pub fn bbox(pts: &[P2]) -> (P2, P2) {
    let mut lo = [f64::INFINITY, f64::INFINITY];
    let mut hi = [f64::NEG_INFINITY, f64::NEG_INFINITY];
    for p in pts {
        lo[0] = lo[0].min(p[0]);
        lo[1] = lo[1].min(p[1]);
        hi[0] = hi[0].max(p[0]);
        hi[1] = hi[1].max(p[1]);
    }
    (lo, hi)
}

/// The ring turned to start at its lowest point (least y, then least x).
pub fn start_lowest(ring: &[P2]) -> Vec<P2> {
    if ring.is_empty() {
        return Vec::new();
    }
    let mut k = 0;
    for (i, p) in ring.iter().enumerate() {
        let q = ring[k];
        if p[1] < q[1] || (p[1] == q[1] && p[0] < q[0]) {
            k = i;
        }
    }
    let mut out = Vec::with_capacity(ring.len());
    out.extend_from_slice(&ring[k..]);
    out.extend_from_slice(&ring[..k]);
    out
}

// ---------------------------------------------------------------- arcs

/// A circular arc through `a` and `b`, turning `sweep` radians about its centre (counter-clockwise
/// positive): its centre, radius and the angle of `a` from the centre.
#[derive(Clone, Copy, Debug)]
pub struct Arc {
    pub centre: P2,
    pub radius: f64,
    pub a0: f64,
    pub sweep: f64,
}

impl Arc {
    /// The arc from a to b turning `deg` degrees (counter-clockwise positive).
    pub fn new(a: P2, b: P2, deg: f64) -> Arc {
        let sweep = deg.to_radians();
        let chord = sub(b, a);
        let c = len(chord);
        let half = sweep / 2.0;
        let radius = c / 2.0 / half.sin().abs();
        let mid = lerp(a, b, 0.5);
        // the centre is to the left of a→b for a counter-clockwise arc under a half turn
        let d = c / 2.0 / half.tan();
        let n = left(unit(chord));
        let centre = add(mid, scale(n, d));
        let a0 = (a[1] - centre[1]).atan2(a[0] - centre[0]);
        Arc { centre, radius, a0, sweep }
    }
    pub fn at(&self, t: f64) -> P2 {
        let ang = self.a0 + self.sweep * t;
        [self.centre[0] + self.radius * ang.cos(), self.centre[1] + self.radius * ang.sin()]
    }
    pub fn length(&self) -> f64 {
        self.radius * self.sweep.abs()
    }
}

/// Whether an arc of `deg` degrees counts as straight.
pub fn straight(deg: f64) -> bool {
    deg.to_radians().abs() < 1e-9
}

//! The planar graph of lines in plan (wall centre lines, room separation lines): the lines split
//! where they cross or touch, their ends welded within a tolerance, and the faces they bound,
//! traced edge by edge as the original does (each line's two sides in the order the lines come).

use super::*;

/// How close two points are to count as one, mm.
pub const WELD: f64 = 1.0;

#[derive(Clone, Debug, Default)]
pub struct Graph {
    pub verts: Vec<P2>,
    /// Undirected edges in the order of the lines and along each; half-edge 2i runs edges[i].0 to
    /// edges[i].1, 2i+1 back. `src[i]` is the line the edge came from.
    pub edges: Vec<(usize, usize)>,
    pub src: Vec<usize>,
}

#[derive(Clone, Debug)]
pub struct Face {
    /// Vertex indices round the face, starting where the tracing started.
    pub ring: Vec<usize>,
    /// The lines (sources) of its edges, one per edge.
    pub lines: Vec<usize>,
    pub area: f64,
}

impl Graph {
    fn vid(&mut self, p: P2, tol: f64) -> usize {
        for (i, v) in self.verts.iter().enumerate() {
            if dist(*v, p) <= tol {
                return i;
            }
        }
        self.verts.push(p);
        self.verts.len() - 1
    }

    /// The graph of segments (in order), split where they cross or touch.
    pub fn build(segs: &[(P2, P2)], tol: f64) -> Graph {
        let mut g = Graph::default();
        let n = segs.len();
        // crossings first, each as a point along the later line
        for j in 0..n {
            for i in 0..j {
                let (a0, a1) = segs[i];
                let (b0, b1) = segs[j];
                if let Some(p) = crossing(a0, a1, b0, b1, tol) {
                    g.vid(p, tol);
                }
            }
        }
        for s in segs {
            g.vid(s.0, tol);
            g.vid(s.1, tol);
        }
        // each line cut at the vertices on it
        let mut seen: std::collections::HashSet<(usize, usize)> = std::collections::HashSet::new();
        for (si, s) in segs.iter().enumerate() {
            let (a, b) = *s;
            let d = sub(b, a);
            let l2 = dot(d, d);
            if l2 <= 0.0 {
                continue;
            }
            let ia = g.vid(a, tol);
            let ib = g.vid(b, tol);
            let mut on: Vec<(f64, usize)> = Vec::new();
            for (vi, v) in g.verts.iter().enumerate() {
                if vi == ia || vi == ib {
                    continue;
                }
                let t = dot(sub(*v, a), d) / l2;
                if t <= 0.0 || t >= 1.0 {
                    continue;
                }
                if seg_dist(a, b, *v) <= tol {
                    on.push((t, vi));
                }
            }
            on.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
            let mut chain = vec![ia];
            for (_, vi) in on {
                if *chain.last().unwrap() != vi {
                    chain.push(vi);
                }
            }
            if *chain.last().unwrap() != ib {
                chain.push(ib);
            }
            for w in chain.windows(2) {
                let (u, v) = (w[0], w[1]);
                if u == v {
                    continue;
                }
                let k = (u.min(v), u.max(v));
                if seen.insert(k) {
                    g.edges.push((u, v));
                    g.src.push(si);
                }
            }
        }
        g
    }

    /// Each vertex's neighbours (by edge index), sorted by angle.
    fn fans(&self) -> Vec<Vec<(f64, usize, usize)>> {
        let mut out: Vec<Vec<(f64, usize, usize)>> = vec![Vec::new(); self.verts.len()];
        for (ei, &(a, b)) in self.edges.iter().enumerate() {
            let pa = self.verts[a];
            let pb = self.verts[b];
            out[a].push(((pb[1] - pa[1]).atan2(pb[0] - pa[0]), b, ei));
            out[b].push(((pa[1] - pb[1]).atan2(pa[0] - pb[0]), a, ei));
        }
        for o in out.iter_mut() {
            o.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
        }
        out
    }

    /// Every face, traced from each half-edge not yet walked, in the half-edges' order: at each
    /// vertex the walk takes the edge next clockwise from the one it came in by, so a bounded
    /// region comes out counter-clockwise and the outside of each connected part clockwise.
    pub fn faces(&self) -> Vec<Face> {
        let fans = self.fans();
        let m = self.edges.len();
        let mut used = vec![false; 2 * m];
        let mut faces = Vec::new();
        for h in 0..2 * m {
            if used[h] {
                continue;
            }
            let mut ring = Vec::new();
            let mut lines = Vec::new();
            let mut cur = h;
            let mut guard = 0;
            loop {
                used[cur] = true;
                let (a, b) = self.edges[cur / 2];
                let (u, v) = if cur % 2 == 0 { (a, b) } else { (b, a) };
                ring.push(u);
                lines.push(self.src[cur / 2]);
                // at v, the edge next clockwise from v→u
                let fan = &fans[v];
                let k = fan.iter().position(|x| x.2 == cur / 2 && x.1 == u).unwrap_or(0);
                let next = fan[(k + fan.len() - 1) % fan.len()];
                let ne = next.2;
                let (na, _) = self.edges[ne];
                cur = if na == v { 2 * ne } else { 2 * ne + 1 };
                guard += 1;
                if cur == h || guard > 4 * m + 4 {
                    break;
                }
            }
            let pts: Vec<P2> = ring.iter().map(|i| self.verts[*i]).collect();
            let a = area(&pts);
            faces.push(Face { ring, lines, area: a });
        }
        faces
    }

    pub fn pts(&self, ring: &[usize]) -> Vec<P2> {
        ring.iter().map(|i| self.verts[*i]).collect()
    }

    /// Which connected part each vertex is in.
    pub fn parts(&self) -> Vec<usize> {
        let n = self.verts.len();
        let mut p: Vec<usize> = (0..n).collect();
        fn find(p: &mut Vec<usize>, x: usize) -> usize {
            let mut r = x;
            while p[r] != r {
                r = p[r];
            }
            let mut y = x;
            while p[y] != r {
                let nx = p[y];
                p[y] = r;
                y = nx;
            }
            r
        }
        for &(a, b) in &self.edges {
            let ra = find(&mut p, a);
            let rb = find(&mut p, b);
            if ra != rb {
                p[ra.max(rb)] = ra.min(rb);
            }
        }
        (0..n).map(|i| find(&mut p, i)).collect()
    }
}

/// Where the segments a and b cross or touch, as a point along b; None when they don't, or lie
/// along each other.
pub fn crossing(a0: P2, a1: P2, b0: P2, b1: P2, tol: f64) -> Option<P2> {
    let d = sub(a1, a0);
    let e = sub(b1, b0);
    let den = cross(d, e);
    let la = len(d);
    let lb = len(e);
    if la <= 0.0 || lb <= 0.0 {
        return None;
    }
    if den.abs() <= 1e-12 * la * lb {
        return None;
    }
    let w = sub(b0, a0);
    let t = cross(w, e) / den;
    let u = cross(w, d) / den;
    let ta = tol / la;
    let tb = tol / lb;
    if t >= -ta && t <= 1.0 + ta && u >= -tb && u <= 1.0 + tb {
        let u = u.clamp(0.0, 1.0);
        Some([b0[0] + u * e[0], b0[1] + u * e[1]])
    } else {
        None
    }
}

/// Chords of an arc from a to b turning `deg` degrees, none further than `tol` from it: the
/// points along it, ends included.
pub fn arc_points(a: P2, b: P2, deg: f64, tol: f64) -> Vec<P2> {
    let arc = Arc::new(a, b, deg);
    let n = chord_count(arc.radius, arc.sweep, tol);
    let mut pts = Vec::with_capacity(n + 1);
    pts.push(a);
    for i in 1..n {
        let ang = arc.a0 + arc.sweep * i as f64 / n as f64;
        pts.push([arc.centre[0] + arc.radius * ang.cos(), arc.centre[1] + arc.radius * ang.sin()]);
    }
    let ang = arc.a0 + arc.sweep;
    pts.push([arc.centre[0] + arc.radius * ang.cos(), arc.centre[1] + arc.radius * ang.sin()]);
    pts
}

/// How many chords an arc of this radius and sweep takes to stay within `tol` of it.
pub fn chord_count(radius: f64, sweep: f64, tol: f64) -> usize {
    if !(radius > tol) {
        return 1.max((sweep.abs() / (std::f64::consts::PI / 2.0)).ceil() as usize);
    }
    let step = 2.0 * (1.0 - tol / radius).acos();
    let n = (sweep.abs() / step).ceil();
    if n.is_finite() && n >= 1.0 {
        (n as usize).min(100_000)
    } else {
        1
    }
}

