//! Sketches: lines (straight, arcs, polylines, circles, ellipses, splines) drawn in any order and
//! either way round, solved into closed loops (outlines counter-clockwise, holes clockwise), or
//! every problem with the lines it's about. Also the problems of a ring's edges, which is how an
//! outline given as points is judged simple.

use super::P2;
use crate::json::Value;

/// A sketch line: its curve, kept as given, and the straight pieces it is drawn with.
#[derive(Clone, Debug)]
pub struct Line {
    /// The part id it was sent back with (edit_boundary keeps it).
    pub id: Option<u64>,
    /// The value it was given as (what the element keeps).
    pub given: Value,
    /// Its points along it, ends included.
    pub pts: Vec<P2>,
}

#[derive(Clone, Debug)]
pub enum Problem {
    /// rank 0: a line 1 mm long or less
    Short(usize),
    /// rank 0: an edge whose two points are the same
    Same(usize),
    /// rank 1: two lines crossing, or one ending part way along another
    Cross(usize, usize, P2),
    /// rank 2: two lines along each other
    Overlap(usize, usize),
    /// rank 3: three or more lines' ends at a point
    Meet(Vec<usize>, P2),
    /// rank 4: an end no other line meets
    Open(usize, P2),
}

impl Problem {
    pub fn rank(&self) -> u8 {
        match self {
            Problem::Short(_) | Problem::Same(_) => 0,
            Problem::Cross(..) => 1,
            Problem::Overlap(..) => 2,
            Problem::Meet(..) => 3,
            Problem::Open(..) => 4,
        }
    }
}

fn pt0(p: P2) -> String {
    format!("[{:.0}, {:.0}]", p[0], p[1])
}

/// The problems said as the messages say them: "line 0 and line 2 intersect at [500, 500]; …".
pub fn describe(probs: &[Problem], word: &str) -> String {
    let mut out = Vec::new();
    for p in probs {
        out.push(match p {
            Problem::Short(i) => format!("{} {} is 1 mm long or less", word, i),
            Problem::Same(i) => format!(
                "{} {} isn't a line it can draw: two points one after another are the same; a line runs between points apart",
                word, i
            ),
            Problem::Cross(i, j, q) => format!("{} {} and {} {} intersect at {}", word, i, word, j, pt0(*q)),
            Problem::Overlap(i, j) => format!("{} {} and {} {} overlap", word, i, word, j),
            Problem::Meet(ls, q) => {
                let names: Vec<String> = ls.iter().map(|l| format!("{} {}", word, l)).collect();
                let list = if names.len() > 1 {
                    format!("{} and {}", names[..names.len() - 1].join(", "), names[names.len() - 1])
                } else {
                    names.join("")
                };
                format!("{} meet at {}: a loop passes a point once", list, pt0(*q))
            }
            Problem::Open(i, q) => format!("{} {} ends at {} without meeting another: the loop is open", word, i, pt0(*q)),
        });
    }
    out.join("; ")
}

const TOL: f64 = 1.0;

/// Where two segments meet at one point (ends included), and the parameters along each.
fn meet(a0: P2, a1: P2, b0: P2, b1: P2) -> Option<(P2, f64, f64)> {
    let d = super::sub(a1, a0);
    let e = super::sub(b1, b0);
    let den = super::cross(d, e);
    if den == 0.0 {
        return None;
    }
    let w = super::sub(b0, a0);
    let t = super::cross(w, e) / den;
    let u = super::cross(w, d) / den;
    let ta = TOL / super::len(d).max(1e-300);
    let tb = TOL / super::len(e).max(1e-300);
    if t >= -ta && t <= 1.0 + ta && u >= -tb && u <= 1.0 + tb {
        Some((super::lerp(a0, a1, t.clamp(0.0, 1.0)), t, u))
    } else {
        None
    }
}

/// Whether two segments lie along each other for more than the tolerance.
fn overlap(a0: P2, a1: P2, b0: P2, b1: P2) -> bool {
    let d = super::sub(a1, a0);
    let l = super::len(d);
    if l <= 0.0 {
        return false;
    }
    let n = [-d[1] / l, d[0] / l];
    let db0 = super::dot(super::sub(b0, a0), n);
    let db1 = super::dot(super::sub(b1, a0), n);
    if db0.abs() > 1e-6 || db1.abs() > 1e-6 {
        return false;
    }
    let u = [d[0] / l, d[1] / l];
    let s0 = super::dot(super::sub(b0, a0), u);
    let s1 = super::dot(super::sub(b1, a0), u);
    let lo = s0.min(s1).max(0.0);
    let hi = s0.max(s1).min(l);
    hi - lo > 1e-6
}

/// The problems of a ring of points taken as the sketch of its edges (edge i from point i to the
/// next).
pub fn ring_problems(ring: &[P2]) -> Vec<Problem> {
    let n = ring.len();
    let lines: Vec<Vec<P2>> = (0..n).map(|i| vec![ring[i], ring[(i + 1) % n]]).collect();
    problems(&lines, true)
}

/// The problems of lines (each a polyline of points), ranked.
pub fn problems(lines: &[Vec<P2>], ring: bool) -> Vec<Problem> {
    let mut probs: Vec<Problem> = Vec::new();
    let mut bad = vec![false; lines.len()];
    for (i, l) in lines.iter().enumerate() {
        let len: f64 = l.windows(2).map(|w| super::dist(w[0], w[1])).sum();
        if ring && l.len() == 2 && l[0] == l[1] {
            probs.push(Problem::Same(i));
            bad[i] = true;
        } else if len <= TOL {
            probs.push(Problem::Short(i));
            bad[i] = true;
        }
    }
    // ends, welded within the tolerance
    let mut nodes: Vec<P2> = Vec::new();
    let mut ends: Vec<Vec<(usize, bool)>> = Vec::new();
    let mut node_of = |p: P2, nodes: &mut Vec<P2>, ends: &mut Vec<Vec<(usize, bool)>>| -> usize {
        for (k, q) in nodes.iter().enumerate() {
            if super::dist(*q, p) <= TOL {
                return k;
            }
        }
        nodes.push(p);
        ends.push(Vec::new());
        nodes.len() - 1
    };
    let mut line_nodes = vec![(0usize, 0usize); lines.len()];
    for (i, l) in lines.iter().enumerate() {
        if bad[i] {
            continue;
        }
        let a = node_of(l[0], &mut nodes, &mut ends);
        ends[a].push((i, false));
        let b = node_of(*l.last().unwrap(), &mut nodes, &mut ends);
        ends[b].push((i, true));
        line_nodes[i] = (a, b);
    }
    // crossings and overlaps, pair by pair
    let mut crosses: Vec<Problem> = Vec::new();
    let mut overlaps: Vec<Problem> = Vec::new();
    for i in 0..lines.len() {
        if bad[i] {
            continue;
        }
        for j in i + 1..lines.len() {
            if bad[j] {
                continue;
            }
            let mut ov = false;
            let mut cross_at: Option<P2> = None;
            for wa in lines[i].windows(2) {
                for wb in lines[j].windows(2) {
                    if overlap(wa[0], wa[1], wb[0], wb[1]) {
                        ov = true;
                    } else if cross_at.is_none() {
                        if let Some((q, _, _)) = meet(wa[0], wa[1], wb[0], wb[1]) {
                            // a meeting at ends welded together is a join, not a crossing
                            let at_i_end = super::dist(q, lines[i][0]) <= TOL || super::dist(q, *lines[i].last().unwrap()) <= TOL;
                            let at_j_end = super::dist(q, lines[j][0]) <= TOL || super::dist(q, *lines[j].last().unwrap()) <= TOL;
                            if !(at_i_end && at_j_end) {
                                cross_at = Some(q);
                            }
                        }
                    }
                }
            }
            if ov {
                overlaps.push(Problem::Overlap(i, j));
            } else if let Some(q) = cross_at {
                crosses.push(Problem::Cross(i, j, q));
            }
        }
    }
    probs.extend(crosses);
    probs.extend(overlaps);
    // three or more ends at a point, and ends no other meets
    let mut meets = Vec::new();
    for (k, e) in ends.iter().enumerate() {
        if e.len() >= 3 {
            let mut ls: Vec<usize> = e.iter().map(|x| x.0).collect();
            ls.sort();
            ls.dedup();
            meets.push(Problem::Meet(ls, nodes[k]));
        }
    }
    probs.extend(meets);
    let mut opens = Vec::new();
    for (i, l) in lines.iter().enumerate() {
        if bad[i] {
            continue;
        }
        let (a, b) = line_nodes[i];
        if ends[a].len() == 1 {
            opens.push(Problem::Open(i, l[0]));
        }
        if ends[b].len() == 1 {
            opens.push(Problem::Open(i, *l.last().unwrap()));
        }
    }
    probs.extend(opens);
    probs.sort_by_key(|p| p.rank());
    probs
}

/// A sketch parameter read into lines (to come: every curve the original takes).
pub fn parse(v: &Value) -> Result<Vec<Line>, String> {
    let Value::Arr(a) = v else {
        return Err(format!("invalid type: {}, expected a sequence", v.kind_name()));
    };
    let mut out = Vec::new();
    for x in a {
        let pts = crate::arch::slabs::de_points(x)?;
        out.push(Line { id: None, given: x.clone(), pts });
    }
    Ok(out)
}

/// One outline and its holes from a sketch, or the message saying what's wrong.
pub fn solve_one(lines: &[Line]) -> Result<(Vec<P2>, Vec<Vec<P2>>), String> {
    let pl: Vec<Vec<P2>> = lines.iter().map(|l| l.pts.clone()).collect();
    let probs = problems(&pl, false);
    if !probs.is_empty() {
        return Err(format!("the lines don't make closed loops: {}", describe(&probs, "line")));
    }
    // follow the lines end to end
    let mut used = vec![false; lines.len()];
    let mut loops: Vec<Vec<P2>> = Vec::new();
    for s in 0..lines.len() {
        if used[s] {
            continue;
        }
        used[s] = true;
        let mut ring: Vec<P2> = lines[s].pts[..lines[s].pts.len() - 1].to_vec();
        let mut end = *lines[s].pts.last().unwrap();
        let start = lines[s].pts[0];
        while super::dist(end, start) > TOL {
            let mut found = false;
            for k in 0..lines.len() {
                if used[k] {
                    continue;
                }
                let l = &lines[k].pts;
                if super::dist(l[0], end) <= TOL {
                    ring.extend_from_slice(&l[..l.len() - 1]);
                    end = *l.last().unwrap();
                    used[k] = true;
                    found = true;
                    break;
                }
                if super::dist(*l.last().unwrap(), end) <= TOL {
                    let rev: Vec<P2> = l.iter().rev().copied().collect();
                    ring.extend_from_slice(&rev[..rev.len() - 1]);
                    end = rev[rev.len() - 1];
                    used[k] = true;
                    found = true;
                    break;
                }
            }
            if !found {
                break;
            }
        }
        loops.push(ring);
    }
    // the outermost loop is the outline, the rest its holes
    let mut outer = 0;
    for (i, l) in loops.iter().enumerate() {
        if super::area(l).abs() > super::area(&loops[outer]).abs() {
            outer = i;
        }
    }
    let outline = super::ccw(&loops[outer]);
    let holes = loops.iter().enumerate().filter(|(i, _)| *i != outer).map(|(_, l)| super::cw(l)).collect();
    Ok((outline, holes))
}

/// What an element keeps of its sketch.
pub fn to_value(lines: &[Line]) -> Value {
    Value::Arr(lines.iter().map(|l| l.given.clone()).collect())
}

//! The engine's judgment of the outlines a command makes or changes (the original's
//! `check_edits`, asked after each command): a floor's, ceiling's, roof's or shaft's boundary, an
//! opening or a courtyard that isn't simple is refused, saying which edges and what to do.

use super::util::*;
use crate::geom::{sketch, P2};
use crate::project::Project;
use std::cell::RefCell;

thread_local! {
    /// Elements the command just ran made over the walls (their outline was the walls').
    static FROM_WALLS: RefCell<Vec<u64>> = const { RefCell::new(Vec::new()) };
    /// What made an element otherwise (a mass, a dormer), for what the message tells to do.
    static MADE_BY: RefCell<Vec<(u64, &'static str)>> = const { RefCell::new(Vec::new()) };
}

/// Forgets what the last command noted (called as each command starts).
pub fn reset() {
    FROM_WALLS.with(|f| f.borrow_mut().clear());
    MADE_BY.with(|f| f.borrow_mut().clear());
}

/// Notes that an element's outline was taken from the walls.
pub fn note_walls(id: u64, yes: bool) {
    if yes {
        FROM_WALLS.with(|f| f.borrow_mut().push(id));
    }
}

/// Notes what made an element (`mass`, `dormer`).
pub fn note_made_by(id: u64, by: &'static str) {
    MADE_BY.with(|f| f.borrow_mut().push((id, by)));
}

fn from_walls(id: u64) -> bool {
    FROM_WALLS.with(|f| f.borrow().contains(&id))
}

fn made_by(id: u64) -> Option<&'static str> {
    MADE_BY.with(|f| f.borrow().iter().find(|x| x.0 == id).map(|x| x.1))
}

/// The rings of an outlined element: (what the message calls it, the ring), in order.
fn rings_of(e: &crate::json::Value) -> Vec<(String, Vec<P2>)> {
    let mut out = Vec::new();
    if let Some(b) = pts(e, "boundary") {
        out.push(("boundary".to_string(), b));
    }
    match cat(e) {
        "roof" => {
            for (i, r) in rings(e, "courtyards").into_iter().enumerate() {
                out.push((format!("courtyard {}", i), r));
            }
            for (i, r) in rings(e, "openings").into_iter().enumerate() {
                out.push((format!("opening {}", i), r));
            }
        }
        "floor" | "ceiling" => {
            for (i, r) in rings(e, "openings").into_iter().enumerate() {
                out.push((format!("opening {}", i), r));
            }
        }
        _ => {}
    }
    out
}

/// Each outline the command made or changed, judged as the sketch of its edges.
pub fn check_edits(before: &Project, after: &Project, cid: &str) -> Result<(), String> {
    for (id, e) in &after.elements {
        let c = cat(e);
        if !matches!(c, "floor" | "ceiling" | "roof" | "shaft") {
            continue;
        }
        let old = before.elements.get(id).filter(|o| cat(o) == c);
        let new_rings = rings_of(e);
        let old_rings = old.map(rings_of).unwrap_or_default();
        for (k, (what, ring)) in new_rings.iter().enumerate() {
            if let Some(o) = old_rings.get(k) {
                if o.0 == *what && o.1 == *ring {
                    continue;
                }
            }
            let probs = sketch::ring_problems(ring);
            if probs.is_empty() {
                continue;
            }
            let said = sketch::describe(&probs, "edge");
            let is_boundary = what == "boundary";
            if old.is_none() {
                let todo = match made_by(*id) {
                    Some("mass") => "redraw the mass whose outline it is".to_string(),
                    Some("dormer") => "from `dormer` change the dormer's width, height or position".to_string(),
                    _ => {
                        if is_boundary {
                            let mut t = "give a simple `boundary` or `sketch`".to_string();
                            if from_walls(*id) {
                                t.push_str(" (walls, or boxes of walls, that touch at a corner enclose no simple outline of their own)");
                            }
                            t
                        } else if what.starts_with("courtyard") {
                            "give simple `courtyards`".to_string()
                        } else {
                            "give simple `openings`".to_string()
                        }
                    }
                };
                let who = if cid == c || matches!(cid, "floor" | "ceiling" | "roof" | "shaft") { cid.to_string() } else { format!("{} {}", c, id) };
                return Err(format!("{}: its {} isn't a simple outline: {}; {}", who, what, said, todo));
            }
            let todo = if c == "roof" && what.starts_with("opening") {
                "give `modify` a simple `openings`"
            } else {
                "redraw it with `edit_boundary`"
            };
            return Err(format!("{} {}: its {} isn't a simple outline: {}; {}", c, id, what, said, todo));
        }
    }
    Ok(())
}

