    let ring = m.ring_at(1.0);
    let mut e = jobj! {
        "guid" => crate::rand::guid(),
        "category" => "roof",
        "type" => type_ref(pr, "roof", &ty),
        "level" => level_guid(pr, level),
        "boundary" => ring_v(&ring),
        "slope" => slope.unwrap_or(0.0),
        "overhang" => overhang.unwrap_or(0.0),
