"""jdiff.py 'command line' [prefix lines...]: run one command (after prefixes) on both, diff the JSON replies
path by path."""
import json, subprocess, sys, tempfile, os, shutil
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/.claude/worktrees/agent-aa380c34464cd9919/target/release/bimcraft-cli')
args = sys.argv[1:]
line = args[0]
pre = args[1:]
def run(exe):
    d = tempfile.mkdtemp()
    open(os.path.join(d, 's.txt'), 'w').write('\n'.join(pre + [line]) + '\n')
    p = subprocess.run([exe, 'run', '--script', 's.txt'], cwd=d, capture_output=True)
    shutil.rmtree(d)
    if p.returncode:
        return p.stderr.decode()
    return json.loads(p.stdout.decode().strip().split('\n')[-1])
o, m = run(ORIG), run(MINE)
diffs = []
def walk(a, b, path):
    if type(a) != type(b):
        diffs.append((path, a, b)); return
    if isinstance(a, dict):
        for k in sorted(set(a) | set(b)):
            if k not in a or k not in b:
                diffs.append((path + '/' + k, a.get(k), b.get(k)))
            else:
                walk(a[k], b[k], path + '/' + k)
    elif isinstance(a, list):
        if len(a) != len(b):
            diffs.append((path + ' len', len(a), len(b)))
        for i, (x, y) in enumerate(zip(a, b)):
            walk(x, y, path + '/%d' % i)
    elif a != b:
        diffs.append((path, a, b))
walk(o, m, '')
print(len(diffs), 'diffs')
for d in diffs[:12]:
    print(' ', d)

