]
outs = [orig(c[0])['regions'][0]['outline'] for c in cases]
def centres(a, b, deg):
    sw = math.radians(deg); c = math.hypot(b[0]-a[0], b[1]-a[1]); half = sw/2
    ux, uy = (b[0]-a[0])/c, (b[1]-a[1])/c
    mx, my = (a[0]+b[0])/2, (a[1]+b[1])/2
