//! Falls: a floor's or flat roof's shape from its drains and the least fall: each drain takes the
//! part of the outline nearer it than any other, ridges run where two parts meet at the top's
//! height, valleys from each drain to each corner of its part, and each drain goes down as far as
//! the fall takes its farthest corner (to the tenth of a millimetre).

use super::shape::{SLine, SPoint, Shape};
use super::util::*;
use crate::commands::params::{self, R};
use crate::geom::{self, P2};
use crate::json::Value;
use crate::session::Session;

fn pc(p: P2) -> String {
    format!("({:.0}, {:.0})", p[0], p[1])
}

/// The polygon clipped to the half-plane nearer `a` than `b` (Sutherland-Hodgman).
fn clip_nearer(poly: &[P2], a: P2, b: P2) -> Vec<P2> {
    let m = geom::lerp(a, b, 0.5);
    let n = geom::sub(b, a);
    // signed distance: negative on a's side
    let sd = |p: P2| geom::dot(geom::sub(p, m), n);
    let k = poly.len();
    let mut out = Vec::with_capacity(k + 2);
    for i in 0..k {
        let cur = poly[i];
        let prev = poly[(i + k - 1) % k];
        let dc = sd(cur);
        let dp = sd(prev);
        let inside_c = dc <= 0.0;
        let inside_p = dp <= 0.0;
        if inside_c {
            if !inside_p {
                let t = dp / (dp - dc);
                out.push(geom::lerp(prev, cur, t));
            }
            out.push(cur);
        } else if inside_p {
            let t = dp / (dp - dc);
            out.push(geom::lerp(prev, cur, t));
        }
    }
    out
}

/// Whether segment p-q lies on one of the ring's edges.
fn on_outline(rings: &[Vec<P2>], p: P2, q: P2) -> bool {
    for r in rings {
        let n = r.len();
        for i in 0..n {
            let (a, b) = (r[i], r[(i + 1) % n]);
            if geom::seg_dist(a, b, p) <= 1e-6 && geom::seg_dist(a, b, q) <= 1e-6 {
                return true;
            }
        }
    }
    false
}

/// Whether the drain sees the corner: the segment between them crosses no edge of the region.
fn sees(rings: &[Vec<P2>], d: P2, c: P2) -> bool {
    for r in rings {
        let n = r.len();
        for i in 0..n {
            let (a, b) = (r[i], r[(i + 1) % n]);
            let o1 = geom::orient(a, b, d);
            let o2 = geom::orient(a, b, c);
            let o3 = geom::orient(d, c, a);
            let o4 = geom::orient(d, c, b);
            let eps = 1e-9 * geom::dist(a, b).max(1.0) * geom::dist(d, c).max(1.0);
            if ((o1 > eps && o2 < -eps) || (o1 < -eps && o2 > eps)) && ((o3 > eps && o4 < -eps) || (o3 < -eps && o4 > eps)) {
                return false;
            }
        }
    }
    // the middle of the way inside the region
    let m = geom::lerp(d, c, 0.5);
    let outline = &rings[0];
    if !(geom::inside(outline, m) || (0..outline.len()).any(|i| geom::seg_dist(outline[i], outline[(i + 1) % outline.len()], m) < 1e-6)) {
        return false;
    }
    for h in &rings[1..] {
        if geom::inside(h, m) {
            return false;
        }
    }
    true
}

pub fn cmd_falls(s: &mut Session, p: &Value) -> R<Value> {
    let c = "falls";
    let idv = match opt_ref(p, c, "id")? {
        Some(v) => v,
        None => return Err("falls: `id`, the floor or flat roof to shape, is required".into()),
    };
    let pr = &s.project;
    let Some(id) = by_ref(pr, &idv) else {
        return Err(format!("falls: no element {}", ref_word(pr, &idv)));
    };
    let e = pr.el(id).unwrap().clone();
    match cat(&e) {
        "floor" => {}
        "roof" => {
            if let Some(why) = super::shape::unshapeable(&e) {
                return Err(format!("falls: {}: {}", id, why));
            }
        }
        _ => return Err(format!("falls: {}: only floors and flat roofs have shapes", id)),
    }
    let drains: Vec<P2> = match params::get(p, "drains") {
        Some(Value::Arr(a)) => {
            let mut out = Vec::new();
            for x in a {
                match params::point_of(x) {
                    Some(q) => out.push(q),
                    None => return Err(format!("falls: `drains`: {} is not a point [x, y] in mm", x.to_compact())),
                }
            }
            out
        }
        _ => return Err("falls: `drains` [[x, y], …] is required".into()),
    };
    let fall = match params::get(p, "fall") {
        None => return Err("falls: `fall`, the least fall in %, is required".into()),
        Some(v) => match params::mm_of(v) {
            Some(x) => x,
            None => return Err(format!("falls: `fall` must be a number in mm, got {}", v.to_compact())),
        },
    };
    let ridges = match params::get(p, "ridges") {
        None => Vec::new(),
        Some(v) => super::slabs::de_rings(v).map_err(|er| format!("falls: `ridges` is a list of lines [[x, y], [x, y]]: {}", er))?,
    };
    if !(fall > 0.0 && fall <= 100.0) {
        return Err(format!("falls: `fall` is a percentage over 0 and at most 100, not {}", d(fall)));
    }
    if drains.is_empty() {
        return Err("falls: give at least one drain".into());
    }
    let (b, holes) = super::shape::region(&e);
    let mut all_rings = vec![b.clone()];
    all_rings.extend(holes.iter().cloned());
    for q in &drains {
        let inside = geom::inside(&b, *q) && !holes.iter().any(|h| geom::inside(h, *q) || (0..h.len()).any(|i| geom::seg_dist(h[i], h[(i + 1) % h.len()], *q) < 1e-9));
        if !inside {
            return Err(format!("falls: the drain at {} is outside the outline", pc(*q)));
        }
    }
    for i in 0..drains.len() {
        for j in i + 1..drains.len() {
            if geom::dist(drains[i], drains[j]) <= 1.0 {
                return Err(format!(
                    "falls: the drains at {} and {} are within a millimetre of each other: one is enough",
                    pc(drains[i]),
                    pc(drains[j])
                ));
            }
        }
    }
    if !ridges.is_empty() {
        return Err("falls: ridges drawn aren't read yet".into());
    }
    // each drain's part, its valleys and the ridges round it
    let corners: Vec<P2> = b.iter().chain(holes.iter().flatten()).copied().collect();
    let mut points: Vec<SPoint> = drains.iter().map(|q| SPoint { id: None, guid: None, at: *q, z: 0.0 }).collect();
    let mut extra: Vec<P2> = Vec::new();
    let mut lines: Vec<SLine> = Vec::new();
    let mut ridge_done: Vec<(P2, P2)> = Vec::new();
    let near = |a: P2, b: P2| geom::dist(a, b) <= 1e-3;
    for (i, dq) in drains.iter().enumerate() {
        let mut cell = b.clone();
        for (j, other) in drains.iter().enumerate() {
            if j != i {
                cell = clip_nearer(&cell, *dq, *other);
            }
        }
        // drop repeated corners
        let mut clean: Vec<P2> = Vec::new();
        for q in cell {
            if clean.last().map(|l| near(*l, q)).unwrap_or(false) {
                continue;
            }
            clean.push(q);
        }
        while clean.len() > 1 && near(clean[0], *clean.last().unwrap()) {
            clean.pop();
        }
        let mut far: f64 = 0.0;
        for q in &clean {
            if !sees(&all_rings, *dq, *q) {
                return Err(format!(
                    "falls: the drain at {} can't see the corner at {} across the outline or a ridge: add a drain on that side",
                    pc(*dq),
                    pc(*q)
                ));
            }
            far = far.max(geom::dist(*dq, *q));
        }
        let depth = (far * fall / 100.0 * 10.0).ceil() / 10.0;
        points[i].z = -depth;
        for q in &clean {
            if !corners.iter().any(|c0| near(*c0, *q)) && !extra.iter().any(|x| near(*x, *q)) && !drains.iter().any(|x| near(*x, *q)) {
                extra.push(*q);
            }
            lines.push(SLine { id: None, guid: None, a: *dq, b: *q });
        }
        let n = clean.len();
        for k in 0..n {
            let (a, b2) = (clean[k], clean[(k + 1) % n]);
            if on_outline(&all_rings, a, b2) {
                continue;
            }
            if ridge_done.iter().any(|(x, y)| (near(*x, a) && near(*y, b2)) || (near(*x, b2) && near(*y, a))) {
                continue;
            }
            ridge_done.push((a, b2));
            lines.push(SLine { id: None, guid: None, a, b: b2 });
        }
    }
    for q in extra {
        points.push(SPoint { id: None, guid: None, at: q, z: 0.0 });
    }
    let mut sh = Shape { points, lines };
    let v = sh.to_value(&mut s.project);
    let el = s.project.el_mut(id).unwrap();
    let order: &[&str] = if cat(el) == "roof" { super::roofs::ORDER } else { super::slabs::FLOOR_ORDER };
    put(el, order, "shape", v);
    let pr = &s.project;
    let e = pr.el(id).unwrap();
    let sh = Shape::read(e);
    let (lo, hi) = super::shape::top_range(pr, e, &sh);
    let drains_v: Vec<Value> = sh.points.iter().take(drains.len()).map(|p| jobj! {"at" => pv(p.at), "z" => p.z}).collect();
    Ok(jobj! {
        "drains" => Value::Arr(drains_v),
        "faces" => super::shape::faces(e, &sh),
        "id" => id,
        "top" => Value::Arr(vec![Value::f(lo), Value::f(hi)]),
    })
}

