    if e.get("extrusion").map(|x| !x.is_null()).unwrap_or(false) {
        return (Vec::new(), 0.0);
    }
    let b = pts(e, "boundary").unwrap_or_default();
    if b.len() < 3 {
        return (Vec::new(), 0.0);
    }
    let yards = rings(e, "courtyards");
    let gables = gable_edges(e);
    let eave = eave_height(pr, e);
    let flat = numd(e, "slope", 30.0) == 0.0;
    // rings the skeleton's way round, each edge keeping its number
    let mut rs: Vec<Vec<P2>> = Vec::new();
    let mut nums: Vec<usize> = Vec::new();
    let mut k0 = 0;
    for (ri, r) in std::iter::once(&b).chain(yards.iter()).enumerate() {
        let n = r.len();
        let want_ccw = ri == 0;
        let is_ccw = geom::area(r) > 0.0;
        if want_ccw == is_ccw {
            rs.push(r.clone());
            nums.extend((0..n).map(|i| k0 + i));
        } else {
            // reversed: point i is old point n-1-i; edge i (i to i+1) is old edge n-2-i
            let rev: Vec<P2> = r.iter().rev().copied().collect();
            rs.push(rev);
            nums.extend((0..n).map(|i| k0 + (2 * n - 2 - i) % n));
        }
        k0 += n;
    }
    let total = k0;
    let slopes: Vec<f64> = (0..total).map(|k| edge_slope_deg(e, k)).collect();
    let min_tan = slopes
        .iter()
        .enumerate()
        .filter(|(k, _)| !gables.contains(k))
        .map(|(_, s)| s.to_radians().tan())
        .fold(f64::INFINITY, f64::min);
    let speeds: Vec<f64> = nums
        .iter()
        .map(|&k| {
            if gables.contains(&k) {
                0.0
            } else if flat || !min_tan.is_finite() || min_tan <= 0.0 {
                1.0
            } else {
                min_tan / slopes[k].to_radians().tan()
            }
        })
        .collect();
    let sk = crate::geom::skeleton::Skeleton::new(&rs, &speeds);
    let rings_f = sk.faces();
    let mut out = Vec::new();
    for (i, ring) in rings_f.into_iter().enumerate() {
        let k = nums[i];
        let (a, _, n, _) = sk.edges[i];
        let tan = if flat || gables.contains(&k) { 0.0 } else { slopes[k].to_radians().tan() };
        out.push(Face { ring, edge: k, origin: a, z0: eave, grad: geom::scale(n, tan) });
    }
    let tmax = sk.t_max;
    (out, if flat || !min_tan.is_finite() { 0.0 } else { tmax * min_tan })
}

/// The underside of a roof by footprint at a point in plan (its lowest face there), None outside.
pub fn underside_at(pr: &Project, e: &Value, q: P2) -> Option<f64> {
    let (faces, _) = roof_faces(pr, e);
    let mut best: Option<f64> = None;
    for f in &faces {
        if f.ring.len() >= 3 && geom::area(&f.ring).abs() > 1e-6 && (geom::inside(&f.ring, q) || on_ring(&f.ring, q)) {
            let z = f.z_at(q);
            best = Some(best.map(|b: f64| b.min(z)).unwrap_or(z));
        }
    }
    best
}

fn on_ring(r: &[P2], q: P2) -> bool {
    let n = r.len();
    (0..n).any(|i| geom::seg_dist(r[i], r[(i + 1) % n], q) < 1e-6)
}

/// The roof's ridge: the highest its underside reaches, mm above zero.
pub fn ridge(pr: &Project, e: &Value) -> f64 {
    let (_, rise) = roof_faces(pr, e);
    eave_height(pr, e) + rise
}
