99	/// The footprint of the walls of a level, `extra` past their faces, and its courtyards: the outline
100	/// counter-clockwise from its lowest corner, each courtyard clockwise from its lowest.
101	pub fn wall_footprint(pr: &Project, level: u64, extra: f64) -> Option<(Vec<P2>, Vec<Vec<P2>>)> {
102	    let o = super::outline::level_outline(pr, level)?;
103	    let walls = super::outline::level_walls(pr, level);
104	    let mut half = Vec::new();
105	    for (w, pieces) in walls.iter().zip(super::walls::joined_centres(&walls)) {
106	        for _ in pieces {
107	            half.push(w.thickness / 2.0);
108	        }
109	    }
110	    let g = &o.graph;
111	    let dist_of = |a: usize, b: usize| -> f64 {
112	        let k = g.edges.iter().position(|&(u, v)| (u == a && v == b) || (u == b && v == a));
113	        k.map(|k| half[g.src[k]]).unwrap_or(0.0) + extra
114	    };
115	    // the outline: the outer face (clockwise) moved outward is the left of the reversed ring
116	    let ring_ids: Vec<usize> = o.faces[o.outer].ring.iter().rev().copied().collect();
117	    let ring = g.pts(&ring_ids);
118	    let n = ring_ids.len();
119	    let ds: Vec<f64> = (0..n).map(|i| -dist_of(ring_ids[i], ring_ids[(i + 1) % n])).collect();
120	    let moved = geom::offset::offset_ring(&ring, &ds);
121	    let boundary = round3(&geom::start_lowest(&super::outline::drop_collinear(&moved)));
122	    // courtyards: the loops the floor is open over, moved in by their faces and the overhang
123	    let mut courtyards = Vec::new();
124	    let parts = g.parts();
125	    let main_part = parts[o.faces[o.outer].ring[0]];
126	    let rooms = super::outline::room_points(pr, level);
127	    let outline_pts: Vec<P2> = ring.clone();
128	    let mut taken: Vec<Vec<P2>> = Vec::new();
129	    for (i, f) in o.faces.iter().enumerate() {
130	        if i == o.outer || f.area >= 0.0 || parts[f.ring[0]] == main_part {
131	            continue;
132	        }
133	        let pts = g.pts(&f.ring);
134	        if !pts.iter().all(|p| geom::inside(&outline_pts, *p)) {
135	            continue;
136	        }
137	        if taken.iter().any(|t| geom::inside_raw(t, pts[0])) {
138	            continue;
139	        }
140	        let region: Vec<P2> = pts.iter().rev().copied().collect();
141	        if rooms.iter().any(|r| geom::inside(&region, *r)) {
142	            continue;
143	        }
144	        taken.push(pts.clone());
145	        let m = f.ring.len();
146	        let ds: Vec<f64> = (0..m).map(|k| -dist_of(f.ring[k], f.ring[(k + 1) % m])).collect();
147	        let moved = geom::offset::offset_ring(&pts, &ds);
148	        courtyards.push(round3(&geom::start_lowest(&super::outline::drop_collinear(&moved))));
149	    }
150	    Some((boundary, courtyards))
151	}
