156	    let tol = crate::geom::graph::WELD;
157	    let mut out = Vec::with_capacity(walls.len());
158	    for (i, w) in walls.iter().enumerate() {
159	        if w.is_arc() {
160	            out.push(w.centre_pieces());
161	            continue;
162	        }
