164	        let dir = geom::sub(w.end, w.start);
165	        for (k, p) in [w.start, w.end].iter().enumerate() {
166	            // the first other straight wall the end touches, not in line with it
167	            let mut target: Option<&Wall> = None;
168	            for (j, o) in walls.iter().enumerate() {
