197	/// Where two lines (through a0, a1 and through b0, b1) meet.
198	pub fn line_meet(a0: P2, a1: P2, b0: P2, b1: P2) -> Option<P2> {
199	    let d = geom::sub(a1, a0);
200	    let e = geom::sub(b1, b0);
201	    let den = geom::cross(d, e);
202	    if den == 0.0 {
203	        return None;
204	    }
205	    let t = geom::cross(geom::sub(b0, a0), e) / den;
206	    Some([a0[0] + d[0] * t, a0[1] + d[1] * t])
207	}
