210	pub fn location_shift(pr: &Project, type_name: &str, location: &str, t: f64) -> f64 {
211	    let ls = layers(pr, "wall", type_name);
212	    // the core: from the first structure layer to the last, else the whole wall
213	    let mut acc = 0.0;
214	    let mut core: Option<(f64, f64)> = None;
215	    for (f, th) in &ls {
216	        if f == "structure" {
217	            core = Some(match core {
218	                None => (acc, acc + th),
219	                Some((a, _)) => (a, acc + th),
220	            });
221	        }
222	        acc += th;
223	    }
224	    let (c0, c1) = core.unwrap_or((0.0, t));
225	    let s = match location {
226	        "exterior-finish" => 0.0,
227	        "interior-finish" => t,
228	        "exterior-core" => c0,
229	        "interior-core" => c1,
230	        "core-centre" => (c0 + c1) / 2.0,
231	        _ => t / 2.0,
232	    };
