442	/// Whether an arc of `deg` degrees from a to b is one the model takes: under a full turn either
443	/// way, its circle within 1000 km of the origin (a turn under 1e-9 rad is straight).
444	pub fn arc_ok(a: P2, b: P2, deg: f64) -> bool {
445	    if !deg.is_finite() || deg.abs() >= 360.0 {
446	        return false;
447	    }
448	    if geom::straight(deg) {
449	        return true;
450	    }
451	    let arc = Arc::new(a, b, deg);
452	    let reach = arc.centre[0].abs().max(arc.centre[1].abs()) + arc.radius;
453	    reach.is_finite() && reach <= params::MAX_MM
454	}
