456	/// The model's rules for one wall, in the original's order.
457	pub fn check_wall(pr: &Project, id: u64, e: &Value) -> R<()> {
458	    check_type(pr, id, e, "wall")?;
459	    let w = match Wall::read(pr, id) {
460	        Some(w) => w,
461	        None => return Ok(()),
462	    };
463	    let l = geom::dist(w.start, w.end);
464	    if !(l > 1.0) {
465	        return Err(format!("wall {}: too short ({} mm)", id, d(l)));
466	    }
467	    if !arc_ok(w.start, w.end, w.arc) {
468	        return Err(format!(
469	            "wall {}: arc {}° isn't between -360° and 360°, reaching no farther than 1000 km",
470	            id,
471	            d(w.arc)
472	        ));
473	    }
474	    for k in ["attach_top", "attach_base"] {
475	        if let Some(v) = e.get(k) {
476	            if v.is_null() {
477	                continue;
478	            }
479	            let ok = by_ref(pr, v).map(|t| matches!(pr.category(t), Some("roof") | Some("floor"))).unwrap_or(false);
480	            if !ok {
481	                return Err(format!("wall {}: {} {} isn't a roof or a floor", id, k, ref_word(pr, v)));
482	            }
483	        }
484	    }
485	    if w.top_level.is_none() && !(w.height > 0.0) {
486	        return Err(format!("wall {} height must be above zero, got {}", id, d(w.height)));
487	    }
