489	    let top = w.top(pr);
490	    if !(top - base > 1.0) {
491	        let tall = (top - base).round() as i64;
492	        return Err(format!(
493	            "wall {}: its top ({:.0} mm) must be above its base ({:.0} mm); it comes out {} mm tall, so raise its top constraint, top offset or height by more than {} mm",
494	            id,
495	            top,
496	            base,
497	            tall,
498	            -tall
499	        ));
