102	    /// The centre line's ends (the location line moved `shift` to its right).
103	    pub fn centre(&self) -> (P2, P2) {
104	        if self.shift == 0.0 {
105	            return (self.start, self.end);
106	        }
107	        if self.is_arc() {
108	            let a = self.arc();
109	            // to the right of a counter-clockwise arc is away from its centre
110	            let r = if a.sweep > 0.0 { a.radius + self.shift } else { a.radius - self.shift };
111	            let a1 = a.a0 + a.sweep;
112	            let s = [a.centre[0] + r * a.a0.cos(), a.centre[1] + r * a.a0.sin()];
113	            let e = [a.centre[0] + r * a1.cos(), a.centre[1] + r * a1.sin()];
114	            return (s, e);
115	        }
116	        let n = geom::unit(geom::sub(self.end, self.start));
117	        let right = [n[1], -n[0]];
118	        (geom::add(self.start, geom::scale(right, self.shift)), geom::add(self.end, geom::scale(right, self.shift)))
119	    }
120	
121	    /// The centre line as straight pieces (an arc in chords within a millimetre).
122	    pub fn centre_pieces(&self) -> Vec<(P2, P2)> {
123	        let (s, e) = self.centre();
124	        if self.is_arc() {
125	            let pts = crate::geom::graph::arc_points(s, e, self.arc, 1.0);
126	            pts.windows(2).map(|w| (w[0], w[1])).collect()
127	        } else {
128	            vec![(s, e)]
129	        }
130	    }
