138	/// The shape triangulated over its region: the triangulation and each corner's height above the
139	/// unshaped top.
140	pub fn lift(e: &Value, sh: &Shape) -> Option<(Triangulation, Vec<f64>)> {
141	    let (b, holes) = region(e);
142	    let pts: Vec<P2> = sh.points.iter().map(|p| p.at).collect();
143	    let lines: Vec<(P2, P2)> = sh.lines.iter().map(|l| (l.a, l.b)).collect();
144	    let t = tri::constrained(&b, &holes, &pts, &lines).ok()?;
145	    let z: Vec<f64> = t
146	        .pts
147	        .iter()
148	        .map(|q| sh.points.iter().find(|p| geom::dist(p.at, *q) <= tri::TOL).map(|p| p.z).unwrap_or(0.0))
149	        .collect();
150	    Some((t, z))
151	}
