153	/// The planes a shaped top folds into (1 for none).
154	pub fn faces(e: &Value, sh: &Shape) -> usize {
155	    if sh.is_empty() {
156	        return 1;
157	    }
158	    match lift(e, sh) {
159	        Some((t, z)) => tri::planes(&t, &z),
160	        None => 1,
161	    }
162	}
