164	/// The top's lowest and highest, mm above zero.
165	pub fn top_range(pr: &Project, e: &Value, sh: &Shape) -> (f64, f64) {
166	    let base = base_top(pr, e);
167	    let (b, holes) = region(e);
168	    let mut zs: Vec<f64> = Vec::new();
169	    for q in b.iter().chain(holes.iter().flatten()) {
170	        zs.push(sh.points.iter().find(|p| geom::dist(p.at, *q) <= tri::TOL).map(|p| p.z).unwrap_or(0.0));
171	    }
172	    for p in &sh.points {
173	        zs.push(p.z);
174	    }
175	    let lo = zs.iter().cloned().fold(f64::INFINITY, f64::min);
176	    let hi = zs.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
177	    (base + lo, base + hi)
178	}
