181	pub fn height_at(e: &Value, sh: &Shape, q: P2) -> f64 {
182	    if sh.points.is_empty() {
183	        return 0.0;
184	    }
185	    match lift(e, sh) {
186	        Some((t, z)) => tri::height_at(&t, &z, q).unwrap_or(0.0),
187	        None => 0.0,
188	    }
189	}
