69	pub fn check_edits(before: &Project, after: &Project, cid: &str) -> Result<(), String> {
70	    for (id, e) in &after.elements {
71	        let c = cat(e);
72	        if !matches!(c, "floor" | "ceiling" | "roof" | "shaft") {
73	            continue;
74	        }
75	        let old = before.elements.get(id).filter(|o| cat(o) == c);
76	        let new_rings = rings_of(e);
77	        let old_rings = old.map(rings_of).unwrap_or_default();
78	        for (k, (what, ring)) in new_rings.iter().enumerate() {
79	            if let Some(o) = old_rings.get(k) {
80	                if o.0 == *what && o.1 == *ring {
81	                    continue;
82	                }
83	            }
84	            // a ring of too few points is the model's to refuse
85	            if ring.len() < 3 || ring.len() > 10000 {
86	                continue;
87	            }
88	            let probs = sketch::ring_problems(ring);
89	            if probs.is_empty() {
90	                continue;
91	            }
92	            let said = sketch::describe(&probs, "edge");
93	            let is_boundary = what == "boundary";
94	            if old.is_none() {
95	                let todo = match made_by(*id) {
96	                    Some("mass") => "redraw the mass whose outline it is".to_string(),
97	                    Some("dormer") => "from `dormer` change the dormer's width, height or position".to_string(),
98	                    _ => {
99	                        if is_boundary {
100	                            let mut t = "give a simple `boundary` or `sketch`".to_string();
101	                            if from_walls(*id) {
102	                                t.push_str(" (walls, or boxes of walls, that touch at a corner enclose no simple outline of their own)");
103	                            }
104	                            t
105	                        } else if what.starts_with("courtyard") {
106	                            "give simple `courtyards`".to_string()
107	                        } else {
108	                            "give simple `openings`".to_string()
109	                        }
110	                    }
111	                };
112	                let who = if cid == c || matches!(cid, "floor" | "ceiling" | "roof" | "shaft") { cid.to_string() } else { format!("{} {}", c, id) };
113	                return Err(format!("{}: its {} isn't a simple outline: {}; {}", who, what, said, todo));
114	            }
115	            let todo = if c == "roof" && what.starts_with("opening") {
116	                "give `modify` a simple `openings`"
117	            } else {
118	                "redraw it with `edit_boundary`"
119	            };
120	            return Err(format!("{} {}: its {} isn't a simple outline: {}; {}", c, id, what, said, todo));
121	        }
122	    }
123	    Ok(())
124	}
