262	pub fn cmd_wall(s: &mut Session, p: &Value) -> R<Value> {
263	    let c = "wall";
264	    let points: Vec<P2> = match params::get(p, "points") {
265	        Some(Value::Arr(a)) => {
266	            let mut out = Vec::new();
267	            for x in a {
268	                match params::point_of(x) {
269	                    Some(q) => out.push(q),
270	                    None => return Err(format!("wall: `points`: {} is not a point [x, y] in mm", x.to_compact())),
271	                }
272	            }
273	            out
274	        }
275	        _ => return Err("wall: `points` [[x, y], …] is required".into()),
276	    };
277	    if points.len() < 2 {
278	        return Err("wall: `points` needs at least 2 points".into());
279	    }
280	    let closed = params::opt_bool(p, c, "closed")?.unwrap_or(false);
281	    let pr = &s.project;
282	    let level = crate::model::level_param(pr, c, p, "level")?;
283	    let ty = params::opt_text(p, c, "type")?;
284	    let height = params::opt_num(p, c, "height")?;
285	    let top_level = match params::get(p, "top_level") {
286	        Some(v) => Some(crate::model::resolve_level(pr, c, "top_level", v)?),
287	        None => None,
288	    };
289	    let base_offset = params::opt_num(p, c, "base_offset")?;
290	    let top_offset = params::opt_num(p, c, "top_offset")?;
291	    let arc = params::opt_num(p, c, "arc")?;
292	    let location = match params::opt_text(p, c, "location")? {
293	        None => None,
294	        Some(l) => match parse_location(&l) {
295	            Some(x) => Some(x),
296	            None => {
297	                return Err(format!(
298	                    "wall: `location` is one of centre, core-centre, exterior-finish, interior-finish, exterior-core, interior-core, not `{}`",
299	                    l
300	                ))
301	            }
302	        },
303	    };
304	    let attach_top = opt_ref(p, c, "attach_top")?;
305	    let attach_base = opt_ref(p, c, "attach_base")?;
306	    let room_bounding = match params::get(p, "room_bounding") {
307	        None => None,
308	        Some(Value::Bool(b)) => Some(*b),
309	        Some(_) => return Err("wall: `room_bounding` is true or false".into()),
310	    };
311	    let ty = ty.or_else(|| default_type(pr, "wall")).ok_or_else(|| "wall: the model has no types for this".to_string())?;
312	    // up to the next level, unless it is given a height (unconnected) or a top level
