1	//! What a wall attaches to: the top and the underside of a floor or a roof as planar pieces in
2	//! plan, and the heights an attached wall's base and top reach over its footprint.
3	
4	use super::util::*;
5	use crate::geom::{self, P2};
6	use crate::json::Value;
7	use crate::project::Project;
8	
9	/// A planar piece of a surface: its ring in plan and its plane, z = z0 + g . (q - o).
10	#[derive(Clone, Debug)]
11	pub struct Piece {
12	    pub ring: Vec<P2>,
13	    pub o: P2,
14	    pub z0: f64,
15	    pub g: P2,
16	}
17	
18	impl Piece {
19	    pub fn z_at(&self, q: P2) -> f64 {
20	        self.z0 + geom::dot(self.g, geom::sub(q, self.o))
21	    }
22	
23	    fn holds(&self, q: P2) -> bool {
24	        let n = self.ring.len();
25	        n >= 3 && (geom::inside_raw(&self.ring, q) || (0..n).any(|i| geom::seg_dist(self.ring[i], self.ring[(i + 1) % n], q) <= 1e-6))
26	    }
27	}
28	
29	/// The plane through three points with heights: (origin, z there, gradient).
30	fn plane3(p: [P2; 3], z: [f64; 3]) -> (P2, f64, P2) {
31	    let e1 = geom::sub(p[1], p[0]);
32	    let e2 = geom::sub(p[2], p[0]);
33	    let (d1, d2) = (z[1] - z[0], z[2] - z[0]);
34	    let det = geom::cross(e1, e2);
35	    if det.abs() < 1e-12 {
36	        return (p[0], z[0], [0.0, 0.0]);
37	    }
38	    (p[0], z[0], [(d1 * e2[1] - d2 * e1[1]) / det, (e1[0] * d2 - e2[0] * d1) / det])
39	}
40	
41	fn level_base(pr: &Project, e: &Value) -> f64 {
42	    level_of(pr, e).map(|l| elev(pr, l)).unwrap_or(0.0) + numd(e, "offset", 0.0)
43	}
44	
45	fn own_thickness(pr: &Project, e: &Value, c: &str) -> f64 {
46	    type_name(pr, e).map(|n| thickness(pr, c, &n)).unwrap_or(0.0)
47	}
48	
49	/// A shaped top's triangles over the outline as if its openings were closed (a roof's
50	/// courtyards stay open), each corner lifted by the point there: the pieces of the top.
51	fn shaped_pieces(e: &Value, base: f64) -> Option<Vec<Piece>> {
52	    let sh = super::shape::Shape::read(e);
53	    if sh.is_empty() {
54	        return None;
55	    }
56	    let b = pts(e, "boundary").unwrap_or_default();
57	    let holes = if cat(e) == "roof" { rings(e, "courtyards") } else { Vec::new() };
58	    let ps: Vec<P2> = sh.points.iter().map(|p| p.at).collect();
59	    let lines: Vec<(P2, P2)> = sh.lines.iter().map(|l| (l.a, l.b)).collect();
60	    let t = crate::geom::tri::constrained(&b, &holes, &ps, &lines).ok()?;
61	    let z: Vec<f64> = t
62	        .pts
63	        .iter()
64	        .map(|q| sh.points.iter().find(|p| geom::dist(p.at, *q) <= crate::geom::tri::TOL).map(|p| p.z).unwrap_or(0.0))
65	        .collect();
66	    let mut out = Vec::new();
67	    for tr in &t.tris {
68	        let p = [t.pts[tr[0]], t.pts[tr[1]], t.pts[tr[2]]];
69	        let (o, z0, g) = plane3(p, [base + z[tr[0]], base + z[tr[1]], base + z[tr[2]]]);
70	        out.push(Piece { ring: p.to_vec(), o, z0, g });
71	    }
72	    Some(out)
73	}
74	
75	/// The pieces of a floor's or a roof's top (`top`) or underside.
76	pub fn pieces(pr: &Project, e: &Value, top: bool) -> Vec<Piece> {
77	    match cat(e) {
78	        "floor" => floor_pieces(pr, e, top),
79	        "roof" => roof_pieces(pr, e, top),
80	        _ => Vec::new(),
81	    }
82	}
83	
84	fn floor_pieces(pr: &Project, e: &Value, top: bool) -> Vec<Piece> {
85	    let b = pts(e, "boundary").unwrap_or_default();
86	    if b.len() < 3 {
87	        return Vec::new();
88	    }
89	    let t = own_thickness(pr, e, "floor");
90	    let base = level_base(pr, e);
91	    if let Some(mut ps) = shaped_pieces(e, base) {
92	        if !top {
93	            for p in ps.iter_mut() {
94	                p.z0 -= t;
95	            }
96	        }
97	        return ps;
98	    }
99	    let slope = numd(e, "slope", 0.0);
100	    let arrow = pts(e, "arrow");
101	    let (o, g, plumb) = match &arrow {
102	        Some(a) if slope != 0.0 && a.len() == 2 && geom::dist(a[0], a[1]) > 0.0 => {
103	            let u = geom::unit(geom::sub(a[1], a[0]));
104	            let r = slope.to_radians();
105	            (a[0], geom::scale(u, r.tan()), t / r.cos())
106	        }
107	        _ => (b[0], [0.0, 0.0], t),
108	    };
109	    let z0 = if top { base } else { base - plumb };
110	    vec![Piece { ring: b, o, z0, g }]
111	}
112	
113	fn roof_pieces(pr: &Project, e: &Value, top: bool) -> Vec<Piece> {
114	    let t = own_thickness(pr, e, "roof");
115	    let base = level_base(pr, e);
116	    if let Some(x) = e.get("extrusion").filter(|x| !x.is_null()) {
117	        return extrusion_pieces(x, base, t, top);
118	    }
119	    if numd(e, "slope", 30.0) == 0.0 {
120	        if let Some(mut ps) = shaped_pieces(e, base) {
121	            if top {
122	                for p in ps.iter_mut() {
123	                    p.z0 += t;
124	                }
125	            }
126	            return ps;
127	        }
128	    }
129	    let (faces, _) = super::roofs::roof_faces(pr, e);
130	    let mut out = Vec::new();
131	    for f in faces {
132	        if f.ring.len() < 3 {
133	            continue;
134	        }
135	        let tan = geom::len(f.grad);
136	        let lift = if top { t * (1.0 + tan * tan).sqrt() } else { 0.0 };
137	        out.push(Piece { ring: f.ring, o: f.origin, z0: f.z0 + lift, g: f.grad });
138	    }
139	    out
140	}
141	
142	/// An extrusion's pieces: between each two points of its profile, across from `from` to `to`
143	/// left of its line.
144	fn extrusion_pieces(x: &Value, base: f64, t: f64, top: bool) -> Vec<Piece> {
145	    let line = pts(x, "line").unwrap_or_default();
146	    let prof = pts(x, "profile").unwrap_or_default();
147	    if line.len() < 2 || geom::dist(line[0], line[1]) <= 0.0 {
148	        return Vec::new();
149	    }
150	    let from = numd(x, "from", 0.0);
151	    let to = numd(x, "to", 0.0);
152	    let a = line[0];
153	    let u = geom::unit(geom::sub(line[1], line[0]));
154	    let n = geom::left(u);
155	    let at = |s: f64, w: f64| geom::add(a, geom::add(geom::scale(u, s), geom::scale(n, w)));
156	    let mut out = Vec::new();
157	    for k in 0..prof.len().saturating_sub(1) {
158	        let (s0, h0) = (prof[k][0], prof[k][1]);
159	        let (s1, h1) = (prof[k + 1][0], prof[k + 1][1]);
160	        if s1 == s0 {
161	            continue;
162	        }
163	        let m = (h1 - h0) / (s1 - s0);
164	        let lift = if top { t * (1.0 + m * m).sqrt() } else { 0.0 };
165	        let ring = vec![at(s0, from), at(s1, from), at(s1, to), at(s0, to)];
166	        out.push(Piece { ring, o: at(s0, from), z0: base + h0 + lift, g: geom::scale(u, m) });
167	    }
168	    out
169	}
170	
171	/// The surface's height at q (the first piece holding it), None off it.
172	pub fn z_at(ps: &[Piece], q: P2) -> Option<f64> {
173	    ps.iter().find(|p| p.holds(q)).map(|p| p.z_at(q))
174	}
