def norm(s):
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'G%d' % len(m)
        return m[g]
    return GUID.sub(rep, s)
def run(exe, lines):
    d = tempfile.mkdtemp(prefix='r')
    open(os.path.join(d, 's.txt'), 'w').write('\n'.join(lines) + '\n')
    p = subprocess.run([exe, 'run', '--script', 's.txt', '--save', 'o.bimcraft'], cwd=d, capture_output=True, timeout=300)
    out = p.stdout.decode() + '\nERR:' + p.stderr.decode() + '\nEXIT %d' % p.returncode
    f = os.path.join(d, 'o.bimcraft')
    if os.path.exists(f):
        out += '\n' + open(f).read()
    shutil.rmtree(d)
    return norm(out)
verbose = '-v' in sys.argv
files = [a for a in sys.argv[1:] if a != '-v']
tot_same = tot_diff = 0
for fn in files:
    text = open(fn).read()
    raw = [l for l in text.split('\n')]
    groups = []
    if '\n\n' in text.strip():
        cur = []
        for l in raw:
            if not l.strip():
                if cur: groups.append(cur); cur = []
            elif not l.startswith('#'):
                cur.append(l)
        if cur: groups.append(cur)
    else:
        groups = [[l] for l in raw if l.strip() and not l.startswith('#')]
    same = diff = 0
    for g in groups:
        a = run(ORIG, g)
        b = run(MINE, g)
        if a == b:
            same += 1
        else:
