#!/usr/bin/env python3
"""Search arc formula combinations against several original arcs (cached)."""
import json, subprocess, sys, tempfile, os, shutil, math, itertools, pickle
ORIG = '/workspace/executable'
CACHE = '/tmp/arch-agent/arccache.pkl'
def run(exe, lines):
    d = tempfile.mkdtemp()
    open(os.path.join(d, 's.txt'), 'w').write('\n'.join(lines) + '\n')
    p = subprocess.run([exe, 'run', '--script', 's.txt'], cwd=d, capture_output=True)
    shutil.rmtree(d)
    return p.stdout.decode().strip().split('\n')[-1]
def orig_arc(ax, ay, bx, by, deg):
    cmd = 'sketch {"lines": [{"start": [%r,%r], "end": [%r,%r]}, {"start": [%r,%r], "end": [%r,%r], "arc": %r}]}' % (bx, by, ax, ay, ax, ay, bx, by, deg)
    o = json.loads(run(ORIG, [cmd]))
    pts = [tuple(p) for p in o['regions'][0]['outline']]
    a = (ax, ay); b = (bx, by)
    k = pts.index(a)
    pts = pts[k:] + pts[:k]
    if pts[1] == b:
        pts = [pts[0]] + list(reversed(pts[1:]))
    return pts
CASES = [(0,0,1000,0,180), (1000,0,0,0,90), (0,0,1000,300,-70), (100,200,3100,-700,45), (0,0,0,2000,120), (-500,300,700,900,-200)]
try:
    cache = pickle.load(open(CACHE, 'rb'))
except Exception:
    cache = {}
for cs in CASES:
    if cs not in cache:
        cache[cs] = orig_arc(*[float(x) for x in cs])
pickle.dump(cache, open(CACHE, 'wb'))
PI = math.pi
def rad(d): return d * (PI / 180.0)
def gen(a, b, deg, n):
    sw = rad(deg)
    dx, dy = b[0]-a[0], b[1]-a[1]
    c = math.hypot(dx, dy)
    h = sw / 2
    mids = {'mid*.5': ((a[0]+b[0])*0.5, (a[1]+b[1])*0.5), 'mid/2': ((a[0]+b[0])/2, (a[1]+b[1])/2), 'a+ch/2': (a[0]+dx/2, a[1]+dy/2), 'a+ch*.5': (a[0]+dx*0.5, a[1]+dy*0.5)}
    rs = {'c/2/|sin|': c/2/abs(math.sin(h)), 'c/(2|sin|)': c/(2*abs(math.sin(h))), '(c/2)/|sin|': (c/2)/abs(math.sin(h)), 'c*.5/|sin|': c*0.5/abs(math.sin(h))}
    for (mn, m), (rn, r) in itertools.product(mids.items(), rs.items()):
        ds = {'c/2/tan': c/2/math.tan(h), 'r*cos*sgn': r*math.cos(h)*(1 if math.sin(h) > 0 else -1), 'c/(2tan)': c/(2*math.tan(h)), '(c/2)cos/sin': (c/2)*math.cos(h)/math.sin(h)}
        norms = {'(-dy,dx)/c': (-dy/c, dx/c), 'unit-left': (-(dy/c), dx/c)}
        for (dn, dd), (nn, nv) in itertools.product(ds.items(), norms.items()):
            for cn in ['m+n*d', 'm+(n*d)']:
                C = (m[0] + nv[0]*dd, m[1] + nv[1]*dd)
                a0 = math.atan2(a[1]-C[1], a[0]-C[0])
                for an in ['a0+rad(deg*i/n)', 'a0+sw*i/n', 'a0+rad(deg*(i/n))', 'a0+sw*(i/n)', 'a0+i*(sw/n)']:
                    def ang(i):
                        if an == 'a0+rad(deg*i/n)': return a0 + rad(deg*i/n)
                        if an == 'a0+sw*i/n': return a0 + sw*i/n
                        if an == 'a0+rad(deg*(i/n))': return a0 + rad(deg*(i/n))
                        if an == 'a0+sw*(i/n)': return a0 + sw*(i/n)
                        return a0 + i*(sw/n)
                    for pn in ['C+r*cs', 'C+cs*r']:
                        if pn == 'C+r*cs':
                            pts = [(C[0] + r*math.cos(ang(i)), C[1] + r*math.sin(ang(i))) for i in range(n+1)]
                        else:
                            pts = [(C[0] + math.cos(ang(i))*r, C[1] + math.sin(ang(i))*r) for i in range(n+1)]
                        yield (mn, rn, dn, nn, an, pn), pts
score = {}
for cs, pts in cache.items():
    n = len(pts) - 1
    a = (float(cs[0]), float(cs[1])); b = (float(cs[2]), float(cs[3]))
    for key, q in gen(a, b, float(cs[4]), n):
        bad = sum(1 for i in range(1, n) if q[i] != pts[i])
        score[key] = score.get(key, 0) + bad
best = sorted(score.items(), key=lambda kv: kv[1])[:10]
for k, v in best:
    print(v, k)
print('total interior pts', sum(len(p)-2 for p in cache.values()))

