    out = {}
    for mn, m in ms.items():
        for dn, dd in {'c/2/tan': c/2/math.tan(h), 'c/(2tan)': c/(2*math.tan(h)), 'rcos': (c/2/math.sin(h))*math.cos(h)}.items():
