            for i in range(1, n):
                for an, th in angles(a0, a1, sw, deg, n, i).items():
                    for pn in ('C+r*cs', 'rot'):
                        if pn == 'C+r*cs':
                            q = (C[0] + r*math.cos(th), C[1] + r*math.sin(th))
                        else:
                            v = (a[0]-C[0], a[1]-C[1])
                            d = th - a0
                            q = (C[0] + v[0]*math.cos(d) - v[1]*math.sin(d), C[1] + v[0]*math.sin(d) + v[1]*math.cos(d))
                        k = (cn, rn, an, pn)
                        key_score[k] = key_score.get(k, 0) + (0 if q == pts[i] else 1)
best = sorted(key_score.items(), key=lambda kv: kv[1])[:15]
for k, v in best:
    print(v, k)
print('total', sum(len(p)-2 for p in cache.values()))

