import math, itertools
def unit(v):
    l = math.hypot(*v); return (v[0]/l, v[1]/l)
def cross(a,b): return a[0]*b[1]-a[1]*b[0]
def dot(a,b): return a[0]*b[0]+a[1]*b[1]
def sub(a,b): return (a[0]-b[0], a[1]-b[1])
def left(v): return (-v[1], v[0])
def variants(a, b, c, d):
    out = {}
    D = sub(b,a); E = sub(d,c)
    u = unit(D); v = unit(E)
    dirsA = {'D': D, 'u': u}
    dirsB = {'E': E, 'v': v}
    for (an, A), (bn, B) in itertools.product(dirsA.items(), dirsB.items()):
        den = cross(A, B)
        if den == 0: continue
        for orig_name, P0 in {'a': a, 'b': b}.items():
            t = cross(sub(c, P0), B)/den
            out['%s+%s*t[cross %s,%s]' % (orig_name, an, an, bn)] = (P0[0]+A[0]*t, P0[1]+A[1]*t)
            t2 = cross(sub(d, P0), B)/den
            out['%s+%s*t[cross from d]' % (orig_name, an)] = (P0[0]+A[0]*t2, P0[1]+A[1]*t2)
        n = left(B)
        for orig_name, P0 in {'a': a, 'b': b}.items():
            for qn, Q in {'c': c, 'd': d}.items():
                t = dot(n, sub(Q, P0))/dot(n, A)
                out['%s+%s*(n%s.(%s-%s))/(n.%s)' % (orig_name, an, bn, qn, orig_name, an)] = (P0[0]+A[0]*t, P0[1]+A[1]*t)
