1	//! Stairs, ramps and railings: a stair's risers and runs with landings, a ramp's runs at its slope,
2	//! and railings down a stair's or a ramp's sides or along a path; their rules.
3	
4	use super::util::*;
5	use crate::commands::params::{self, R};
6	use crate::geom::{self, P2};
7	use crate::json::Value;
8	use crate::project::Project;
9	use crate::session::Session;
10	
11	pub const STAIR_ORDER: &[&str] = &["level", "top_level", "height", "start", "angle", "width", "riser", "tread", "landings", "params"];
12	pub const RAMP_ORDER: &[&str] = &["level", "top_level", "height", "start", "angle", "width", "slope", "landings", "params"];
13	pub const RAILING_ORDER: &[&str] = &["type", "level", "path", "base_offset", "host", "side", "params"];
14	
15	/// Landings as serde reads `Vec<Landing {at, turn}>`.
16	fn de_landings(v: &Value) -> Result<Vec<(f64, f64)>, String> {
17	    let Value::Arr(a) = v else {
18	        return Err(format!("invalid type: {}, expected a sequence", v.kind_name()));
19	    };
20	    let mut out = Vec::new();
21	    for x in a {
22	        let Value::Obj(m) = x else {
23	            return Err(format!("invalid type: {}, expected struct Landing", x.kind_name()));
24	        };
25	        let mut at = None;
26	        let mut turn = None;
27	        for (k, y) in &m.items {
28	            match k.as_str() {
29	                "at" => match y {
30	                    Value::Num(n) => at = Some(n.as_f64()),
31	                    o => return Err(format!("invalid type: {}, expected f64", o.kind_name())),
32	                },
33	                "turn" => match y {
34	                    Value::Num(n) => turn = Some(n.as_f64()),
35	                    o => return Err(format!("invalid type: {}, expected f64", o.kind_name())),
36	                },
37	                other => return Err(format!("unknown field `{}`, expected `at` or `turn`", other)),
38	            }
39	        }
40	        let at = at.ok_or_else(|| "missing field `at`".to_string())?;
41	        out.push((at, turn.unwrap_or(0.0)));
42	    }
43	    Ok(out)
44	}
45	
46	/// The angle (degrees from east) a stair climbs toward a point, to a billionth of a degree.
47	pub fn angle_to(a: P2, b: P2) -> f64 {
48	    let deg = (b[1] - a[1]).atan2(b[0] - a[0]).to_degrees();
49	    (deg * 1e9).round() / 1e9
50	}
51	
52	/// The parameters stairs and ramps share: start, angle, level, top, height, width, landings,
53	/// railings.
54	struct Common {
55	    start: P2,
56	    angle: f64,
57	    level: u64,
58	    top: Option<u64>,
59	    height: Option<f64>,
60	    width: Option<f64>,
61	    landings: Option<Vec<(f64, f64)>>,
62	    railings: bool,
63	}
64	
65	fn common(s: &Session, p: &Value, c: &str, own: &mut dyn FnMut() -> R<()>) -> R<Common> {
66	    let start = params::req_point(p, c, "start")?;
67	    let end = params::opt_point(p, c, "end")?;
68	    let angle = params::opt_num(p, c, "angle")?;
69	    let angle = match end {
70	        Some(e) => {
71	            if !(geom::dist(start, e) > 1.0) {
72	                return Err(format!("{}: `end` must be away from `start`: it says which way the {} climbs", c, c));
73	            }
74	            angle_to(start, e)
75	        }
76	        None => angle.unwrap_or(0.0),
77	    };
