18	fn clip_nearer(poly: &[P2], a: P2, b: P2) -> Vec<P2> {
19	    let m = geom::lerp(a, b, 0.5);
20	    let n = geom::sub(b, a);
21	    // signed distance: negative on a's side
22	    let sd = |p: P2| geom::dot(geom::sub(p, m), n);
23	    let k = poly.len();
24	    let mut out = Vec::with_capacity(k + 2);
25	    for i in 0..k {
26	        let cur = poly[i];
27	        let next = poly[(i + 1) % k];
28	        let dc = sd(cur);
29	        let dn = sd(next);
30	        let inside_c = dc <= 0.0;
31	        let inside_n = dn <= 0.0;
32	        if inside_c {
33	            out.push(cur);
