/// The split lines cut at the shape's points within a millimetre of them, in order along each.
pub fn line_pieces(sh: &Shape) -> Vec<(P2, P2)> {
    let mut out = Vec::new();
    for l in &sh.lines {
        let dd = geom::sub(l.b, l.a);
        let l2 = geom::dot(dd, dd);
        let mut cuts: Vec<(f64, P2)> = Vec::new();
        if l2 > 0.0 {
            for p in &sh.points {
                if geom::dist(p.at, l.a) <= 1.0 || geom::dist(p.at, l.b) <= 1.0 {
                    continue;
                }
                let t = geom::dot(geom::sub(p.at, l.a), dd) / l2;
                if t > 0.0 && t < 1.0 && geom::seg_dist(l.a, l.b, p.at) <= 1.0 {
                    cuts.push((t, p.at));
                }
            }
        }
        cuts.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
        let mut prev = l.a;
        for (_, q) in cuts {
            out.push((prev, q));
            prev = q;
        }
        out.push((prev, l.b));
    }
    out
}

