import subprocess, json, tempfile, os, sys
lines = open(sys.argv[1]).read().strip().split('\n')
for exe in ['/workspace/executable', '/workspace/.claude/worktrees/agent-aa380c34464cd9919/target/release/bimcraft-cli']:
