import json, math, pickle, itertools
PI = math.pi
def rad(d): return d * (PI / 180.0)
# wall arc (0,0)->(8000,0) 90 deg, from the floor boundary
b = json.load(open('/tmp/arch-agent/arcwall_pts.json'))
k = b.index([0.0, 0.0]); ring = b[k:] + b[:k]
wall_arc = [tuple(p) for p in ring]
cache = pickle.load(open('/tmp/arch-agent/arccache.pkl', 'rb'))
cases = [((0.0, 0.0), (8000.0, 0.0), 90.0, wall_arc, 'wall')]
for cs, pts in cache.items():
    cases.append(((float(cs[0]), float(cs[1])), (float(cs[2]), float(cs[3])), float(cs[4]), pts, 'sketch'))
def gen(a, b, deg, n):
    sw = rad(deg)
    dx, dy = b[0] - a[0], b[1] - a[1]
    c = math.hypot(dx, dy)
    h = sw / 2
    phi = math.atan2(dy, dx)
    rs = {'c/2/|sin|': c / 2 / abs(math.sin(h)), 'c/(2|sin|)': c / (2 * abs(math.sin(h)))}
    for rn, r in rs.items():
        a0s = {'phi-h-pi/2': phi - h - PI / 2 if sw > 0 else phi - h + PI / 2,
               'phi-(h+pi/2)': phi - (h + PI / 2) if sw > 0 else phi - (h - PI / 2),
               'rad(deg(phi)-deg/2-90)': rad(math.degrees(phi) - deg / 2 - 90) if sw > 0 else rad(math.degrees(phi) - deg / 2 + 90)}
        for an, a0 in a0s.items():
            C = (a[0] - r * math.cos(a0), a[1] - r * math.sin(a0))
            for tn in ['a0+sw*i/n', 'a0+rad(deg*i/n)', 'a0+i*(sw/n)']:
                def th(i):
                    if tn == 'a0+sw*i/n': return a0 + sw * i / n
                    if tn == 'a0+rad(deg*i/n)': return a0 + rad(deg * i / n)
                    return a0 + i * (sw / n)
                pts = [(C[0] + r * math.cos(th(i)), C[1] + r * math.sin(th(i))) for i in range(n + 1)]
                yield (rn, an, tn), pts
score = {}
total = 0
for a, b, deg, pts, kind in cases:
    n = len(pts) - 1
    last = n if kind == 'wall' else n - 1
    total += last
    for key, q in gen(a, b, deg, n):
        bad = sum(1 for i in range(1, last + 1) if q[i] != pts[i])
        score[key] = score.get(key, 0) + bad
for k, v in sorted(score.items(), key=lambda kv: kv[1])[:10]:
    print(v, k)
print('total', total)

