/// The circle of an arc wall's centre line: centre, radius, start angle and sweep.
fn centre_circle(w: &Wall) -> (P2, f64, f64, f64) {
    let a = w.arc();
    let r = if a.sweep > 0.0 { a.radius + w.shift } else { a.radius - w.shift };
    (a.centre, r, a.a0, a.sweep)
}

/// Whether a point lies on an arc wall's location line (within tol).
fn on_arc(w: &Wall, p: P2, tol: f64) -> bool {
    let a = w.arc();
    if (geom::dist(p, a.centre) - a.radius).abs() > tol {
        return false;
    }
    if geom::dist(p, w.start) <= tol || geom::dist(p, w.end) <= tol {
        return true;
    }
    let ang = (p[1] - a.centre[1]).atan2(p[0] - a.centre[0]);
    let mut da = ang - a.a0;
    if a.sweep < 0.0 {
        da = -da;
    }
    da = da.rem_euclid(std::f64::consts::TAU);
    da <= a.sweep.abs()
}

/// Where the line through a and b meets a circle, the meeting nearer `near`.
fn line_circle(a: P2, b: P2, c: P2, r: f64, near: P2) -> Option<P2> {
    let d = geom::unit(geom::sub(b, a));
    let f = geom::sub(a, c);
    let bb = geom::dot(f, d);
    let cc = geom::dot(f, f) - r * r;
    let disc = bb * bb - cc;
    if disc < 0.0 {
        return None;
    }
    let s = disc.sqrt();
    let p1 = geom::add(a, geom::scale(d, -bb - s));
    let p2 = geom::add(a, geom::scale(d, -bb + s));
    Some(if geom::dist(p1, near) <= geom::dist(p2, near) { p1 } else { p2 })
}

/// An arc wall's centre line in chords, each end run on or back round its circle to meet the
/// centre line of the wall its location line's end touches.
fn arc_joined(walls: &[Wall], i: usize, tol: f64) -> Vec<(P2, P2)> {
    let w = &walls[i];
    let (c, r, a0, sweep) = centre_circle(w);
    let (mut t0, mut t1) = (a0, a0 + sweep);
    let mut moved = false;
    for (k, p) in [w.start, w.end].iter().enumerate() {
        let mut target: Option<&Wall> = None;
        for (j, o) in walls.iter().enumerate() {
            if j == i {
                continue;
            }
            let touches = if o.is_arc() { on_arc(o, *p, tol) } else { geom::seg_dist(o.start, o.end, *p) <= tol };
            if touches {
                target = Some(o);
                break;
            }
        }
        let Some(o) = target else { continue };
        let here_ang = if k == 0 { t0 } else { t1 };
        let here = [c[0] + r * here_ang.cos(), c[1] + r * here_ang.sin()];
        let q = if o.is_arc() {
            let (oc, or, _, _) = centre_circle(o);
            circle_circle(c, r, oc, or, here)
        } else {
            let (os, oe) = o.centre();
            line_circle(os, oe, c, r, here)
        };
        if let Some(q) = q {
            // the angle there, the nearest turn to the end's own
            let mut ang = (q[1] - c[1]).atan2(q[0] - c[0]);
            while ang - here_ang > std::f64::consts::PI {
                ang -= std::f64::consts::TAU;
            }
            while here_ang - ang > std::f64::consts::PI {
                ang += std::f64::consts::TAU;
            }
            if (ang - here_ang).abs() > 1e-15 {
                moved = true;
            }
            if k == 0 {
                t0 = ang;
            } else {
                t1 = ang;
            }
        }
    }
    if !moved {
        return w.centre_pieces();
    }
    let sw = t1 - t0;
    let n = crate::geom::graph::chord_count(r, sw, 1.0);
    let at = |t: f64| [c[0] + r * t.cos(), c[1] + r * t.sin()];
    let mut pts = Vec::with_capacity(n + 1);
    for k in 0..=n {
        pts.push(at(t0 + sw * k as f64 / n as f64));
    }
    pts.windows(2).map(|x| (x[0], x[1])).collect()
}

/// Where two circles meet, the meeting nearer `near`.
fn circle_circle(c0: P2, r0: f64, c1: P2, r1: f64, near: P2) -> Option<P2> {
    let d = geom::dist(c0, c1);
    if d <= 0.0 || d > r0 + r1 || d < (r0 - r1).abs() {
        return None;
    }
    let a = (r0 * r0 - r1 * r1 + d * d) / (2.0 * d);
    let h = (r0 * r0 - a * a).max(0.0).sqrt();
    let u = geom::unit(geom::sub(c1, c0));
    let m = geom::add(c0, geom::scale(u, a));
    let n = geom::left(u);
    let p1 = geom::add(m, geom::scale(n, h));
    let p2 = geom::sub(m, geom::scale(n, h));
    Some(if geom::dist(p1, near) <= geom::dist(p2, near) { p1 } else { p2 })
}

