/// The circle of an arc wall's centre line: centre, radius, start angle and sweep.
fn centre_circle(w: &Wall) -> (P2, f64, f64, f64) {
    let a = w.arc();
    let r = if a.sweep > 0.0 { a.radius + w.shift } else { a.radius - w.shift };
    (a.centre, r, a.a0, a.sweep)
}

/// Whether a point lies on an arc wall's location line (within tol).
fn on_arc(w: &Wall, p: P2, tol: f64) -> bool {
    let a = w.arc();
    if (geom::dist(p, a.centre) - a.radius).abs() > tol {
        return false;
    }
    if geom::dist(p, w.start) <= tol || geom::dist(p, w.end) <= tol {
        return true;
    }
    let ang = (p[1] - a.centre[1]).atan2(p[0] - a.centre[0]);
    let mut da = ang - a.a0;
    if a.sweep < 0.0 {
        da = -da;
    }
    da = da.rem_euclid(std::f64::consts::TAU);
    da <= a.sweep.abs()
}

/// Where the line through a and b meets a circle, the meeting nearer `near`.
fn line_circle(a: P2, b: P2, c: P2, r: f64, near: P2) -> Option<P2> {
    let d = geom::unit(geom::sub(b, a));
    let f = geom::sub(a, c);
    let bb = geom::dot(f, d);
    let cc = geom::dot(f, f) - r * r;
    let disc = bb * bb - cc;
    if disc < 0.0 {
        return None;
    }
    let s = disc.sqrt();
    let p1 = geom::add(a, geom::scale(d, -bb - s));
    let p2 = geom::add(a, geom::scale(d, -bb + s));
    Some(if geom::dist(p1, near) <= geom::dist(p2, near) { p1 } else { p2 })
}

