10	#[derive(Clone, Debug, Default)]
11	pub struct Graph {
12	    pub verts: Vec<P2>,
13	    /// Undirected edges in the order of the lines and along each; half-edge 2i runs edges[i].0 to
14	    /// edges[i].1, 2i+1 back. `src[i]` is the line the edge came from.
15	    pub edges: Vec<(usize, usize)>,
16	    pub src: Vec<usize>,
17	}
