28	impl Graph {
29	    fn vid(&mut self, p: P2, tol: f64) -> usize {
30	        for (i, v) in self.verts.iter().enumerate() {
31	            if dist(*v, p) <= tol {
32	                return i;
33	            }
34	        }
35	        self.verts.push(p);
36	        self.verts.len() - 1
37	    }
38	
39	    /// The graph of segments (in order), split where they cross or touch.
40	    pub fn build(segs: &[(P2, P2)], tol: f64) -> Graph {
41	        let mut g = Graph::default();
42	        let n = segs.len();
43	        // crossings first, each as a point along the earlier line
44	        for j in 0..n {
45	            for i in 0..j {
46	                let (a0, a1) = segs[i];
47	                let (b0, b1) = segs[j];
48	                if let Some(p) = crossing(a0, a1, b0, b1, tol) {
49	                    g.vid(p, tol);
50	                }
51	            }
52	        }
53	        for s in segs {
54	            g.vid(s.0, tol);
55	            g.vid(s.1, tol);
56	        }
57	        // each line cut at the vertices on it
58	        let mut seen: std::collections::HashSet<(usize, usize)> = std::collections::HashSet::new();
59	        for (si, s) in segs.iter().enumerate() {
60	            let (a, b) = *s;
61	            let d = sub(b, a);
62	            let l2 = dot(d, d);
63	            if l2 <= 0.0 {
64	                continue;
65	            }
66	            let ia = g.vid(a, tol);
67	            let ib = g.vid(b, tol);
68	            let mut on: Vec<(f64, usize)> = Vec::new();
69	            for (vi, v) in g.verts.iter().enumerate() {
70	                if vi == ia || vi == ib {
71	                    continue;
72	                }
73	                let t = dot(sub(*v, a), d) / l2;
74	                if t <= 0.0 || t >= 1.0 {
75	                    continue;
76	                }
77	                if seg_dist(a, b, *v) <= tol {
78	                    on.push((t, vi));
79	                }
80	            }
81	            on.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
82	            let mut chain = vec![ia];
83	            for (_, vi) in on {
84	                if *chain.last().unwrap() != vi {
85	                    chain.push(vi);
86	                }
87	            }
88	            if *chain.last().unwrap() != ib {
89	                chain.push(ib);
90	            }
91	            for w in chain.windows(2) {
92	                let (u, v) = (w[0], w[1]);
93	                if u == v {
94	                    continue;
95	                }
96	                let k = (u.min(v), u.max(v));
97	                if seen.insert(k) {
98	                    g.edges.push((u, v));
99	                    g.src.push(si);
100	                }
101	            }
102	        }
103	        g
104	    }
