106	    /// Each vertex's neighbours (by edge index), sorted by angle.
107	    fn fans(&self) -> Vec<Vec<(f64, usize, usize)>> {
108	        let mut out: Vec<Vec<(f64, usize, usize)>> = vec![Vec::new(); self.verts.len()];
109	        for (ei, &(a, b)) in self.edges.iter().enumerate() {
110	            let pa = self.verts[a];
111	            let pb = self.verts[b];
112	            out[a].push(((pb[1] - pa[1]).atan2(pb[0] - pa[0]), b, ei));
113	            out[b].push(((pa[1] - pb[1]).atan2(pa[0] - pb[0]), a, ei));
114	        }
115	        for o in out.iter_mut() {
116	            o.sort_by(|x, y| x.0.partial_cmp(&y.0).unwrap_or(std::cmp::Ordering::Equal));
117	        }
118	        out
119	    }
