1	//! The outline of a level's walls: their centre lines as a planar graph, the outer edge of its
2	//! largest part (a floor's or a roof's footprint by default), and the loops standing free inside
3	//! it with no room in them (courtyards, open through floors and roofs).
4	
5	use super::util::*;
6	use super::walls::Wall;
7	use crate::geom::graph::{Face, Graph, WELD};
8	use crate::geom::{self, P2};
9	use crate::project::Project;
10	
11	/// The walls a level's plan of rooms sees: those its computation height cuts.
12	pub fn level_walls(pr: &Project, level: u64) -> Vec<Wall> {
13	    let z = elev(pr, level) + computation_height(pr, level);
14	    Wall::all(pr).into_iter().filter(|w| w.spans(pr, z)).collect()
15	}
16	
17	/// The graph of the walls' centre lines, with which wall each line is.
18	pub fn wall_graph(walls: &[Wall]) -> (Graph, Vec<u64>) {
19	    let mut segs = Vec::new();
20	    let mut src = Vec::new();
21	    for (w, pieces) in walls.iter().zip(super::walls::joined_centres(walls)) {
22	        for s in pieces {
23	            segs.push(s);
24	            src.push(w.id);
25	        }
26	    }
27	    (Graph::build(&segs, WELD), src)
28	}
29	
30	/// The outline of the level's walls along their centre lines and the free-standing loops inside
31	/// it with no room in them, as a floor takes them: the outline counter-clockwise, as the outside
32	/// of the largest part is traced and turned round; each loop clockwise from its lowest corner.
33	pub struct Outline {
34	    pub boundary: Vec<P2>,
35	    pub holes: Vec<Vec<P2>>,
36	    /// The part (graph component) and face the outline is.
37	    pub graph: Graph,
38	    pub faces: Vec<Face>,
39	    pub outer: usize,
40	}
41	
42	/// Rooms' points on a level.
43	pub fn room_points(pr: &Project, level: u64) -> Vec<P2> {
44	    pr.elements
45	        .values()
46	        .filter(|e| cat(e) == "room" && level_of(pr, e) == Some(level))
47	        .filter_map(|e| pt(e, "point"))
48	        .collect()
49	}
