src = src.replace("""joins = dict(joiner=meet_joiner, host=meet_host, joiner_from_end=meet_joiner_from_end)""", """import math
def unit(v):
    l = math.hypot(v[0], v[1])
    return (v[0]/l, v[1]/l)
def unit2(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1])
    return (v[0]/l, v[1]/l)
def meet_unit(a0, a1, b0, b1, un=unit):
    d = un(sub(a1, a0)); e = un(sub(b1, b0)); den = cr(d, e)
    t = cr(sub(b0, a0), e) / den
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
def meet_unit_d(a0, a1, b0, b1, un=unit):
    d = un(sub(a1, a0)); e = sub(b1, b0); den = cr(d, e)
    t = cr(sub(b0, a0), e) / den
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
def meet_unit_e(a0, a1, b0, b1, un=unit):
    d = sub(a1, a0); e = un(sub(b1, b0)); den = cr(d, e)
    t = cr(sub(b0, a0), e) / den
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
def meet_normal(a0, a1, b0, b1, un=unit):
    # host as n.x = c with unit normal; joiner a0 + d t
    e = un(sub(b1, b0)); n = (-e[1], e[0]); c = n[0]*b0[0] + n[1]*b0[1]
    d = sub(a1, a0)
    t = (c - (n[0]*a0[0] + n[1]*a0[1])) / (n[0]*d[0] + n[1]*d[1])
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
def meet_normal_u(a0, a1, b0, b1, un=unit):
    e = un(sub(b1, b0)); n = (-e[1], e[0]); c = n[0]*b0[0] + n[1]*b0[1]
    d = un(sub(a1, a0))
    t = (c - (n[0]*a0[0] + n[1]*a0[1])) / (n[0]*d[0] + n[1]*d[1])
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
def meet_normal_side(a0, a1, b0, b1, un=unit):
    # signed distances of both joiner points from the host line; lerp
    e = un(sub(b1, b0)); n = (-e[1], e[0])
    s0 = n[0]*(a0[0]-b0[0]) + n[1]*(a0[1]-b0[1])
    s1 = n[0]*(a1[0]-b0[0]) + n[1]*(a1[1]-b0[1])
    t = s0 / (s0 - s1)
    d = sub(a1, a0)
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
def meet_side_raw(a0, a1, b0, b1):
    e = sub(b1, b0)
    s0 = cr(e, sub(a0, b0)); s1 = cr(e, sub(a1, b0))
    t = s0 / (s0 - s1)
    d = sub(a1, a0)
    return (a0[0] + d[0]*t, a0[1] + d[1]*t)
