import math, itertools
cr = lambda p, q: p[0]*q[1] - p[1]*q[0]
sub = lambda p, q: (p[0]-q[0], p[1]-q[1])
add = lambda p, q: (p[0]+q[0], p[1]+q[1])
sc = lambda p, k: (p[0]*k, p[1]*k)
def unit_h(v):
    l = math.hypot(v[0], v[1]); return (v[0]/l, v[1]/l)
def unit_s(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); return (v[0]/l, v[1]/l)
def unit_m(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); k = 1.0/l; return (v[0]*k, v[1]*k)
s = (703.0, 6000.0); e = (7283.5, 0.0); h = 100.0
want_b = 7322.24536795871   # at y=100 (E0's inner face)
want_t = 961.0953679587146  # at y=5900 (E2's inner face)
hosts = {
    'b_pts': ((100.0, 100.0), (9900.0, 100.0)),
    'b_pts_rev': ((9900.0, 100.0), (100.0, 100.0)),
    'b_full': ((0.0, 100.0), (10000.0, 100.0)),
    'b_full_rev': ((10000.0, 100.0), (0.0, 100.0)),
}
hosts_t = {
    't_pts': ((9900.0, 5900.0), (100.0, 5900.0)),
    't_pts_rev': ((100.0, 5900.0), (9900.0, 5900.0)),
    't_full': ((10000.0, 5900.0), (0.0, 5900.0)),
    't_full_rev': ((0.0, 5900.0), (10000.0, 5900.0)),
}
def meet(a0, a1, b0, b1, along='a'):
    d = sub(a1, a0); f = sub(b1, b0); den = cr(d, f)
    if along == 'a':
        t = cr(sub(b0, a0), f) / den
        return add(a0, sc(d, t))
    else:
        u = cr(sub(b0, a0), d) / den
        return add(b0, sc(f, u))
results = []
for un_name, un in [('hypot', unit_h), ('sqrt', unit_s), ('mul', unit_m)]:
    d = sub(e, s)
    u = un(d)
    n = (-u[1], u[0])
    for side in (1, -1):
        for build in ('pts', 'pt_dir', 'pt_unit'):
            if build == 'pts':
                a0 = add(s, sc(n, side*h)); a1 = add(e, sc(n, side*h))
            elif build == 'pt_dir':
                a0 = add(s, sc(n, side*h)); a1 = add(a0, d)
            else:
                a0 = add(s, sc(n, side*h)); a1 = add(a0, u)
            for hn, (b0, b1) in hosts.items():
                for along in 'ab':
                    p = meet(a0, a1, b0, b1, along)
                    if p[0] == want_b:
                        results.append(('B', un_name, side, build, hn, along))
            for hn, (b0, b1) in hosts_t.items():
                for along in 'ab':
                    p = meet(a0, a1, b0, b1, along)
                    if p[0] == want_t:
                        results.append(('T', un_name, side, build, hn, along))
for r in results: print(r)
# print some values
d = sub(e, s); u = unit_h(d); n = (-u[1], u[0])
a0 = add(s, sc(n, -h)); a1 = add(e, sc(n, -h))
print(repr(meet(a0, a1, (100.0, 100.0), (9900.0, 100.0))[0]), repr(meet(a0, a1, (9900.0, 5900.0), (100.0, 5900.0))[0]))

