32-/// An extrusion as serde reads `Extrusion {line, profile, from, to}`.
33-pub fn de_extrusion(v: &Value) -> Result<Value, String> {
34-    let Value::Obj(m) = v else {
35:        return Err(format!("invalid type: {}, expected struct Extrusion", v.kind_name()));
36-    };
37-    let mut line = None;
38-    let mut profile = None;
39-    let mut from = None;
40-    let mut to = None;
41-    for (k, x) in &m.items {
42-        match k.as_str() {
43-            "line" => {
44-                let pts = super::slabs::de_points(x)?;
45-                line = Some(pts);
46-            }
47-            "profile" => profile = Some(super::slabs::de_points(x)?),
48-            "from" => match x {
49-                Value::Num(n) => from = Some(n.as_f64()),
50-                o => return Err(format!("invalid type: {}, expected f64", o.kind_name())),
51-            },
52-            "to" => match x {
53-                Value::Num(n) => to = Some(n.as_f64()),
54-                o => return Err(format!("invalid type: {}, expected f64", o.kind_name())),
55-            },
56-            other => return Err(format!("unknown field `{}`, expected one of `line`, `profile`, `from`, `to`", other)),
57-        }
58-    }
59-    let line = line.ok_or_else(|| "missing field `line`".to_string())?;
60-    let profile = profile.ok_or_else(|| "missing field `profile`".to_string())?;
61-    let to = to.ok_or_else(|| "missing field `to`".to_string())?;
62-    Ok(jobj! {
63-        "line" => ring_v(&line),
64-        "profile" => ring_v(&profile),
65-        "from" => from.unwrap_or(0.0),
66-        "to" => to,
67-    })
68-}
