/// The fields of a struct of 4 (`id`, `guid`, then two required ones) given as a sequence.
fn seq4<'a>(f: &'a [Value], name: &str) -> Result<(Option<u64>, &'a Value, Option<&'a Value>), String> {
    let short = |i: usize| format!("invalid length {}, expected struct {} with 4 elements", i, name);
    let id = match f.first() {
        Some(y) => de_id(y)?,
        None => None,
    };
    if let Some(y) = f.get(1) {
        de_ref(y)?;
    }
    let third = f.get(2).ok_or_else(|| short(2))?;
    Ok((id, third, f.get(3)))
}

fn too_long(f: &[Value]) -> Result<(), String> {
    if f.len() > 4 {
        return Err(format!("invalid length {}, expected fewer elements in array", f.len()));
    }
    Ok(())
}

