341	fn edge_lines(g: &Graph, lines: &Lines, ring: &[usize]) -> Vec<usize> {
342	    let n = ring.len();
343	    let mut out = Vec::with_capacity(n);
344	    for i in 0..n {
345	        let (a, b) = (ring[i], ring[(i + 1) % n]);
346	        let k = g.edges.iter().position(|&(u, v)| (u == a && v == b) || (u == b && v == a));
347	        let mut s = k.map(|k| g.src[k]).unwrap_or(usize::MAX);
348	        let (pa, pb) = (g.verts[a], g.verts[b]);
349	        for (t, (q0, q1)) in lines.segs.iter().enumerate() {
350	            if geom::seg_dist(*q0, *q1, pa) <= 1e-6 && geom::seg_dist(*q0, *q1, pb) <= 1e-6 {
351	                let better = s == usize::MAX || lines.half[t] > lines.half[s] || (lines.half[t] == lines.half[s] && t < s);
352	                if better {
353	                    s = t;
354	                }
355	            }
356	        }
357	        out.push(s);
358	    }
