362	/// A ring moved out to the faces as the faces' own tracing gives it: no corner between two
363	/// pieces of one wall's face in line, starting where the first wall's face does.
364	fn as_faces_trace(g: &Graph, lines: &Lines, ring: &[usize], moved: Vec<P2>) -> Vec<P2> {
365	    let n = moved.len();
366	    let src = edge_lines(g, lines, ring);
367	    // corner i lies between edge i-1 and edge i
368	    let keep: Vec<bool> = (0..n)
369	        .map(|i| {
370	            let (prev, next) = (src[(i + n - 1) % n], src[i]);
371	            let a = moved[(i + n - 1) % n];
372	            let b = moved[i];
373	            let c = moved[(i + 1) % n];
374	            let in_line = geom::orient(a, b, c).abs() <= 1e-6 * geom::dist(a, c).max(1.0);
375	            !(prev == next && in_line)
376	        })
377	        .collect();
378	    if keep.iter().filter(|k| **k).count() < 3 {
379	        return moved;
380	    }
381	    // the first edge by its wall's order starts the ring
382	    let mut first = 0;
383	    for i in 0..n {
384	        if keep[i] && (src[i] < src[first] || !keep[first]) {
385	            first = i;
386	        }
387	    }
388	    (0..n).map(|k| (first + k) % n).filter(|i| keep[*i]).map(|i| moved[i]).collect()
389	}
390	
391	/// A ring moved out to the faces that runs across itself cut back to the region round the point.
392	fn untangle(ring: Vec<P2>, q: P2) -> Vec<P2> {
393	    let n = ring.len();
394	    let mut crosses = false;
395	    'outer: for i in 0..n {
396	        for j in i + 2..n {
397	            if i == 0 && j == n - 1 {
398	                continue;
399	            }
400	            let (a0, a1, b0, b1) = (ring[i], ring[(i + 1) % n], ring[j], ring[(j + 1) % n]);
401	            let o1 = geom::orient(a0, a1, b0);
402	            let o2 = geom::orient(a0, a1, b1);
403	            let o3 = geom::orient(b0, b1, a0);
404	            let o4 = geom::orient(b0, b1, a1);
405	            if ((o1 > 0.0 && o2 < 0.0) || (o1 < 0.0 && o2 > 0.0)) && ((o3 > 0.0 && o4 < 0.0) || (o3 < 0.0 && o4 > 0.0)) {
406	                crosses = true;
407	                break 'outer;
408	            }
409	        }
410	    }
411	    if !crosses {
412	        return ring;
413	    }
414	    let segs: Vec<(P2, P2)> = (0..n).map(|i| (ring[i], ring[(i + 1) % n])).collect();
415	    let g = Graph::build(&segs, 1e-6);
416	    let faces = g.faces();
417	    let mut best: Option<(bool, f64, usize)> = None;
418	    for (i, f) in faces.iter().enumerate() {
419	        if f.area <= 0.0 {
420	            continue;
421	        }
422	        let pts = g.pts(&f.ring);
423	        let round = geom::inside(&pts, q);
424	        let better = match best {
425	            None => true,
426	            Some((r, a, _)) => (round && !r) || (round == r && f.area > a),
427	        };
428	        if better {
429	            best = Some((round, f.area, i));
430	        }
431	    }
432	    match best {
433	        Some((_, _, i)) => g.pts(&faces[i].ring),
434	        None => ring,
435	    }

