"""Run the original on many closed wall loops (one per run, saved) and cache each floor's boundary."""
import json, os, subprocess, sys, tempfile, shutil, pickle
ORIG = '/workspace/executable'
CACHE = '/tmp/arch-agent/tri_cache.pkl'
cache = pickle.load(open(CACHE, 'rb')) if os.path.exists(CACHE) else {}
def run(points, extra=''):
    key = (tuple(map(tuple, points)), extra)
    if key in cache:
        return cache[key]
