"""Simulate wall-join arithmetic variants on closed loops and compare corner coordinates with the
original's floor boundaries (cached by tri_probe)."""
import math, pickle, itertools, sys
cr = lambda p, q: p[0]*q[1] - p[1]*q[0]
sub = lambda p, q: (p[0]-q[0], p[1]-q[1])
add = lambda p, q: (p[0]+q[0], p[1]+q[1])
sc = lambda p, k: (p[0]*k, p[1]*k)
dot = lambda p, q: p[0]*q[0] + p[1]*q[1]
def unit(v):
    l = math.hypot(v[0], v[1]); return (v[0]/l, v[1]/l)
def unit_s(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); return (v[0]/l, v[1]/l)

# meeting formulas: line A (a0, a1) meets line B (b0, b1); returns the point
def m_plain_a(a0, a1, b0, b1):
    d = sub(a1, a0); e = sub(b1, b0); den = cr(d, e)
    if den == 0: return None
    return add(a0, sc(d, cr(sub(b0, a0), e) / den))
def m_plain_b(a0, a1, b0, b1):
    return m_plain_a(b0, b1, a0, a1)
def m_unit_a(a0, a1, b0, b1, un=unit):
    d = un(sub(a1, a0)); e = un(sub(b1, b0)); den = cr(d, e)
    if den == 0: return None
    return add(a0, sc(d, cr(sub(b0, a0), e) / den))
def m_unit_b(a0, a1, b0, b1):
    return m_unit_a(b0, b1, a0, a1)
def m_unitd_a(a0, a1, b0, b1):
    d = unit(sub(a1, a0)); e = sub(b1, b0); den = cr(d, e)
    if den == 0: return None
    return add(a0, sc(d, cr(sub(b0, a0), e) / den))
def m_normal_a(a0, a1, b0, b1):
    # B as unit normal line n.x = c; A param a0 + d t
    e = unit(sub(b1, b0)); n = (-e[1], e[0]); c = dot(n, b0)
    d = sub(a1, a0); den = dot(n, d)
    if den == 0: return None
    return add(a0, sc(d, (c - dot(n, a0)) / den))
def m_normal_u_a(a0, a1, b0, b1):
    e = unit(sub(b1, b0)); n = (-e[1], e[0]); c = dot(n, b0)
    d = unit(sub(a1, a0)); den = dot(n, d)
    if den == 0: return None
    return add(a0, sc(d, (c - dot(n, a0)) / den))
def m_det(a0, a1, b0, b1):
    x1, y1 = a0; x2, y2 = a1; x3, y3 = b0; x4, y4 = b1
    D = (x1 - x2)*(y3 - y4) - (y1 - y2)*(x3 - x4)
    if D == 0: return None
    px = ((x1*y2 - y1*x2)*(x3 - x4) - (x1 - x2)*(x3*y4 - y3*x4)) / D
    py = ((x1*y2 - y1*x2)*(y3 - y4) - (y1 - y2)*(x3*y4 - y3*x4)) / D
    return (px, py)
def m_lines(a0, a1, b0, b1):
    n1 = (a1[1]-a0[1], a0[0]-a1[0]); c1 = n1[0]*a0[0] + n1[1]*a0[1]
    n2 = (b1[1]-b0[1], b0[0]-b1[0]); c2 = n2[0]*b0[0] + n2[1]*b0[1]
    D = n1[0]*n2[1] - n1[1]*n2[0]
    if D == 0: return None
    return ((c1*n2[1] - c2*n1[1]) / D, (n1[0]*c2 - n2[0]*c1) / D)
def m_lines_u(a0, a1, b0, b1):
    u1 = unit(sub(a1, a0)); u2 = unit(sub(b1, b0))
    n1 = (-u1[1], u1[0]); c1 = dot(n1, a0)
    n2 = (-u2[1], u2[0]); c2 = dot(n2, b0)
    D = n1[0]*n2[1] - n1[1]*n2[0]
    if D == 0: return None
    return ((c1*n2[1] - c2*n1[1]) / D, (n1[0]*c2 - n2[0]*c1) / D)
FORMS = dict(plain_a=m_plain_a, plain_b=m_plain_b, unit_a=m_unit_a, unit_b=m_unit_b, unitd_a=m_unitd_a,
             normal_a=m_normal_a, normal_u_a=m_normal_u_a, det=m_det, lines=m_lines, lines_u=m_lines_u)

def joins(pts, form, mode, from_end_for_end=False):
    """Closed loop of walls pts[i]->pts[i+1]; each end meets the neighbouring wall's centre line.
    mode: 'simul' (use original lines), 'seq' (walls in order; others' lines as joined so far),
    'seq_own' (own line updated after its start is joined)."""
    n = len(pts)
    lines = [[pts[i], pts[(i + 1) % n]] for i in range(n)]
    orig = [list(l) for l in lines]
    out = [list(l) for l in lines]
    for i in range(n):
        prev = (i - 1) % n; nxt = (i + 1) % n
        src = out if mode.startswith('seq') else orig
        own = list(out[i]) if mode == 'seq_own' else list(orig[i])
        # start meets prev wall
        o = src[prev]
        q = form(own[0], own[1], o[0], o[1])
        if q is not None:
            out[i][0] = q
            if mode == 'seq_own':
                own[0] = q
        o = src[nxt]
        q = form(own[0], own[1], o[0], o[1]) if not from_end_for_end else form(own[1], own[0], o[0], o[1])
        if q is not None:
            out[i][1] = q
    return out

def corners(out, weld):
    n = len(out)
    res = []
    for i in range(n):
        # vertex at pts[i]: wall i's start and wall i-1's end
        s = out[i][0]; e = out[(i - 1) % n][1]
        if weld == 'first':
            res.append(s if i != 0 else e if False else s)
        elif weld == 'seg_first':
            # the lower segment index registers first: wall i-1 for i>0, wall 0 for i == 0
            res.append(e if i > 0 else s)
        elif weld == 'seg_last':
            res.append(s if i > 0 else e)
        elif weld == 'end':
            res.append(e)
        elif weld == 'start':
            res.append(s)
    return res

if __name__ == '__main__':
    cache = pickle.load(open('/tmp/arch-agent/tri_cache.pkl', 'rb'))
    cases = [(list(map(list, k[0])), v) for k, v in cache.items() if v and k[1] == '']
    print(len(cases), 'cases')
    scores = []
    for fname, form in FORMS.items():
        for mode in ('simul', 'seq', 'seq_own'):
            for fe in (False, True):
                for weld in ('seg_first', 'seg_last', 'end', 'start'):
                    ok = 0
                    for pts, want in cases:
                        out = joins([tuple(map(float, p)) for p in pts], form, mode, fe)
                        cs = corners(out, weld)
                        wset = sorted(tuple(p) for p in want)
                        if sorted(tuple(c) for c in cs) == wset:
                            ok += 1
                    scores.append((ok, fname, mode, fe, weld))
    scores.sort(reverse=True)
    for s in scores[:15]:
        print(s)

