import sys, pickle, math, itertools
cr = lambda p, q: p[0]*q[1] - p[1]*q[0]
sub = lambda p, q: (p[0]-q[0], p[1]-q[1])
add = lambda p, q: (p[0]+q[0], p[1]+q[1])
sc = lambda p, k: (p[0]*k, p[1]*k)
dot = lambda p, q: p[0]*q[0] + p[1]*q[1]
def unit(v):
    l = math.hypot(v[0], v[1]); return (v[0]/l, v[1]/l)
def unit_s(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); return (v[0]/l, v[1]/l)
ident = lambda v: v

def param(a0, a1, b0, b1, ua, ub):
    d = ua(sub(a1, a0)); e = ub(sub(b1, b0)); den = cr(d, e)
    if den == 0: return None
    return add(a0, sc(d, cr(sub(b0, a0), e) / den))
def param2(a0, a1, b0, b1, ua, ub):
    # t = cross(e, a0 - b0) / cross(d, e) form (sign flipped arrangement)
    d = ua(sub(a1, a0)); e = ub(sub(b1, b0)); den = cr(e, d)
    if den == 0: return None
    t = cr(e, sub(a0, b0)) / den
    return add(a0, sc(d, t))
def param3(a0, a1, b0, b1, ua, ub):
    d = ua(sub(a1, a0)); e = ub(sub(b1, b0))
    den = d[0]*e[1] - d[1]*e[0]
    if den == 0: return None
    t = ((b0[0]-a0[0])*e[1] - (b0[1]-a0[1])*e[0]) / den
    return (a0[0] + t*d[0], a0[1] + t*d[1])
def lerp(a0, a1, b0, b1, ua, ub):
    d = sub(a1, a0); e = ub(sub(b1, b0)); den = cr(ua(d), e)
    if den == 0: return None
    t = cr(sub(b0, a0), e) / cr(d, e)
    return (a0[0]*(1-t) + a1[0]*t, a0[1]*(1-t) + a1[1]*t)
def cramer(a0, a1, b0, b1, nsign, cpt_a, cpt_b, ua, ub):
    da = ua(sub(a1, a0)); db = ub(sub(b1, b0))
    n1 = (da[1], -da[0]) if nsign else (-da[1], da[0])
    n2 = (db[1], -db[0]) if nsign else (-db[1], db[0])
    c1 = dot(n1, a0 if cpt_a == 0 else a1)
    c2 = dot(n2, b0 if cpt_b == 0 else b1)
    D = n1[0]*n2[1] - n1[1]*n2[0]
    if D == 0: return None
    return ((c1*n2[1] - c2*n1[1]) / D, (n1[0]*c2 - n2[0]*c1) / D)
def det(a0, a1, b0, b1, ua, ub):
    x1, y1 = a0; x2, y2 = a1; x3, y3 = b0; x4, y4 = b1
    D = (x1 - x2)*(y3 - y4) - (y1 - y2)*(x3 - x4)
    if D == 0: return None
    px = ((x1*y2 - y1*x2)*(x3 - x4) - (x1 - x2)*(x3*y4 - y3*x4)) / D
    py = ((x1*y2 - y1*x2)*(y3 - y4) - (y1 - y2)*(x3*y4 - y3*x4)) / D
    return (px, py)

