    # find the apex in the boundary (closest to A)
    ap = min(v, key=lambda p: math.hypot(p[0]-A[0], p[1]-A[1]))
    cases.append((pts, tuple(ap)))
variants = []
uns = (('r', ident), ('h', unit), ('s', unit_s))
W1 = lambda P: (P[1], P[2])
W2 = lambda P: (P[2], P[0])
lines = {'W1': W1, 'W2': W2, 'W1r': lambda P: (P[2], P[1]), 'W2r': lambda P: (P[0], P[2])}
for (an, A_), (bn, B_) in itertools.product(lines.items(), lines.items()):
