    n1 = (da[1], -da[0]) if nsign else (-da[1], da[0])
    n2 = (db[1], -db[0]) if nsign else (-db[1], db[0])
    c1 = dot(n1, a0 if cpt_a == 0 else a1)
    c2 = dot(n2, b0 if cpt_b == 0 else b1)
    D = n1[0]*n2[1] - n1[1]*n2[0]
    if D == 0: return None
