each corner is the earlier wall's joined point (W0's start at O, W(i-1)'s end elsewhere)."""
import sys, pickle, math, itertools
cr = lambda p, q: p[0]*q[1] - p[1]*q[0]
sub = lambda p, q: (p[0]-q[0], p[1]-q[1])
add = lambda p, q: (p[0]+q[0], p[1]+q[1])
sc = lambda p, k: (p[0]*k, p[1]*k)
dot = lambda p, q: p[0]*q[0] + p[1]*q[1]
def u_h(v):
    l = math.hypot(v[0], v[1]); return (v[0]/l, v[1]/l)
def u_s(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); return (v[0]/l, v[1]/l)
def u_m(v):
    l = math.sqrt(v[0]*v[0] + v[1]*v[1]); k = 1.0/l; return (v[0]*k, v[1]*k)
def u_r(v):
    return v
UN = dict(r=u_r, h=u_h, s=u_s, m=u_m)

def meet(p, d, q, e):
    den = cr(d, e)
    if den == 0: return None
    return add(p, sc(d, cr(sub(q, p), e) / den))
def meet_n(p, d, q, e):
    # other line by unit normal
    n = (-e[1], e[0])
    den = dot(n, d)
    if den == 0: return None
    return add(p, sc(d, dot(n, sub(q, p)) / den))

def simulate(pts, un_own, un_oth, origin, seq, passes, fm):
    n = len(pts)
    cur = [[pts[i], pts[(i + 1) % n]] for i in range(n)]
    base = [list(c) for c in cur]
    for _ in range(passes):
        for i in range(n):
            for k in (0, 1):
                o = (i - 1) % n if k == 0 else (i + 1) % n
                oth = cur[o] if seq else base[o]
                own = cur[i] if seq else base[i]
                if origin == 'start':
                    p = own[0]; d = UN[un_own](sub(own[1], own[0]))
                elif origin == 'end_k':
                    p = own[k]; d = UN[un_own](sub(own[1 - k], own[k]))
                else:
                    p = own[1]; d = UN[un_own](sub(own[0], own[1]))
                q0 = oth[0]; e = UN[un_oth](sub(oth[1], oth[0]))
                r = fm(p, d, q0, e)
                if r is not None:
                    cur[i][k] = r
    return cur

cache = pickle.load(open('/tmp/arch-agent/tri_cache.pkl', 'rb'))
cases = []
for key, v in cache.items():
    if not v or key[1] != '':
        continue
    pts = [tuple(map(float, p)) for p in key[0]]
    cases.append((pts, sorted(tuple(p) for p in v)))
scores = []
for un_own, un_oth in itertools.product('rhsm', 'rhsm'):
    for origin in ('start', 'end_k', 'end'):
        for seq in (False, True):
            for passes in (1, 2):
                for fmn, fm in (('meet', meet), ('meet_n', meet_n)):
                    for vert in ('earlier', 'later'):
                        ok = 0
                        for pts, want in cases:
                            cur = simulate(pts, un_own, un_oth, origin, seq, passes, fm)
                            n = len(pts)
                            vs = []
                            for c in range(n):
                                # corner c: wall c-1's end and wall c's start
                                a = cur[(c - 1) % n][1]; b = cur[c][0]
                                if vert == 'earlier':
                                    vs.append(b if c == 0 else a)
                                else:
                                    vs.append(a if c == 0 else b)
                            ok += sorted(vs) == want
                        scores.append((ok, un_own, un_oth, origin, seq, passes, fmn, vert))
scores.sort(key=lambda s: -s[0])
print(len(cases))
for s in scores[:12]:
