    # other line by unit normal
    n = (-e[1], e[0])
    den = dot(n, d)
    if den == 0: return None
    return add(p, sc(d, dot(n, sub(q, p)) / den))

def simulate(pts, un_own, un_oth, origin, seq, passes, fm):
    n = len(pts)
    cur = [[pts[i], pts[(i + 1) % n]] for i in range(n)]
    base = [list(c) for c in cur]
    for _ in range(passes):
        for i in range(n):
            for k in (0, 1):
                o = (i - 1) % n if k == 0 else (i + 1) % n
                oth = cur[o] if seq else base[o]
                own = cur[i] if seq else base[i]
                if origin == 'start':
                    p = own[0]; d = UN[un_own](sub(own[1], own[0]))
                elif origin == 'end_k':
                    p = own[k]; d = UN[un_own](sub(own[1 - k], own[k]))
                else:
                    p = own[1]; d = UN[un_own](sub(own[0], own[1]))
                q0 = oth[0]; e = UN[un_oth](sub(oth[1], oth[0]))
                r = fm(p, d, q0, e)
                if r is not None:
                    cur[i][k] = r
    return cur

